window.PK=window.PK||{};window.PK.glossar=[{"slug":"5-amino-1mq","begriff":"5-Amino-1MQ","begriff_en":"5-Amino-1MQ","kategorie":"wirkstoff","kurz":"Molécula pequeña investigada como inhibidor de NNMT en modelos preclínicos. No es un péptido.","kurz_en":"Molécula pequeña investigada como inhibidor de NNMT en modelos preclínicos. No es un péptido.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 29155147","titel_en":"PubMed: Publicación de investigación, PMID 29155147","url":"https://pubmed.ncbi.nlm.nih.gov/29155147/"}],"text":"El artículo original enlazado investiga inhibidores de NNMT de molécula pequeña en ensayos celulares y un modelo de obesidad inducida por dieta en ratones. No proporciona evidencia clínica para el uso de productos de tienda.","text_en":"El artículo original enlazado investiga inhibidores de NNMT de molécula pequeña en ensayos celulares y un modelo de obesidad inducida por dieta en ratones. No proporciona evidencia clínica para el uso de productos de tienda.","synonyme":["5-Amino 1MQ","5A1MQ","Inhibidor de NNMT"],"synonyme_en":["5-Amino 1MQ","5A1MQ","Inhibidor de NNMT"],"link":"wirkstoffe/5-amino-1mq.html"},{"slug":"affiliate-link","begriff":"Enlace de afiliado","begriff_en":"Enlace de afiliado","kategorie":"vergleich","kurz":"Un enlace de afiliado conduce a una tienda externa y puede activar una comisión por una compra.","kurz_en":"Un enlace de afiliado conduce a una tienda externa y puede activar una comisión por una compra.","quellen":[{"titel":"Peptide Compass: Nuestra información de afiliación","titel_en":"Peptide Compass: Nuestra información de afiliación","url":"https://peptidkompass.com/es/affiliate-hinweis.html"}],"text":"Los enlaces de afiliado llevan una etiqueta de Publicidad directamente en el enlace y además utilizan el atributo nofollow patrocinado. La etiqueta se aplica incluso a enlaces de tienda sin una asociación confirmada. El estado de socio y una posible comisión no cambian cómo se evalúa a un proveedor.","text_en":"Los enlaces de afiliado llevan una etiqueta de Publicidad directamente en el enlace y además utilizan el atributo nofollow patrocinado. La etiqueta se aplica incluso a enlaces de tienda sin una asociación confirmada. El estado de socio y una posible comisión no cambian cómo se evalúa a un proveedor.","siehe":["partnercode"],"seiten":["affiliate-hinweis.html"]},{"slug":"agonist","begriff":"Agonista","begriff_en":"Agonista","kategorie":"grundlagen","kurz":"Una molécula que se une a un receptor y activa su cadena de señalización. Opuesto: antagonista.","kurz_en":"Una molécula que se une a un receptor y activa su cadena de señalización. Opuesto: antagonista.","quellen":[{"titel":"NCI: agonista","titel_en":"NCI: agonista","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/agonist"}],"text":"Un agonista se une a un receptor y activa la cadena de señalización vinculada a él, similar a una llave que abre una cerradura. La contraparte es un antagonista: también se une al receptor pero no activa una cadena de señalización, sino que ocupa el sitio y bloquea que un agonista se una. Los estudios utilizan ambos roles para sondear vías de señalización de receptores de manera dirigida.","text_en":"Un agonista se une a un receptor y activa la cadena de señalización vinculada a él, similar a una llave que abre una cerradura. La contraparte es un antagonista: también se une al receptor pero no activa una cadena de señalización, sino que ocupa el sitio y bloquea que un agonista se una. Los estudios utilizan ambos roles para sondear vías de señalización de receptores de manera dirigida.","siehe":["rezeptor","analogon"]},{"slug":"aliquot","begriff":"Aliquot","begriff_en":"Aliquot","kategorie":"handhabung","kurz":"Una alícuota es una porción pequeña y medida tomada de una solución de laboratorio más grande, generalmente almacenada por separado.","kurz_en":"Una alícuota es una porción pequeña y medida tomada de una solución de laboratorio más grande, generalmente almacenada por separado.","quellen":[{"titel":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","titel_en":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Una alícuota es una porción de muestra separada. Las porciones separadas pueden evitar el ciclado de temperatura repetido del stock completo.","text_en":"Una alícuota es una porción de muestra separada. Las porciones separadas pueden evitar el ciclado de temperatura repetido del stock completo.","siehe":["vial","konzentration","sterilitaet"]},{"slug":"aminosaeure","begriff":"Aminoácido","begriff_en":"Aminoácido","kategorie":"grundlagen","kurz":"El bloque de construcción básico del que se ensamblan los péptidos y las proteínas mediante enlaces peptídicos.","kurz_en":"El bloque de construcción básico del que se ensamblan los péptidos y las proteínas mediante enlaces peptídicos.","quellen":[{"titel":"NCI: aminoácido","titel_en":"NCI: aminoácido","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/amino-acid"}],"text":"Los aminoácidos contienen un grupo amino y un grupo carboxilo. Las proteínas se describen comúnmente utilizando 20 aminoácidos estándar. Los enlaces peptídicos los unen en cadenas; su orden se denomina secuencia.","text_en":"Los aminoácidos contienen un grupo amino y un grupo carboxilo. Las proteínas se describen comúnmente utilizando 20 aminoácidos estándar. Los enlaces peptídicos los unen en cadenas; su orden se denomina secuencia.","synonyme":["Aminoácidos"],"synonyme_en":["Aminoácidos"],"siehe":["peptid","peptidbindung","sequenz"],"seiten":["peptid-1x1.html"]},{"slug":"analogon","begriff":"Análogo","begriff_en":"Análogo","kategorie":"grundlagen","kurz":"Una variante sintéticamente modificada de un péptido endógeno con una estructura ligeramente alterada.","kurz_en":"Una variante sintéticamente modificada de un péptido endógeno con una estructura ligeramente alterada.","quellen":[{"titel":"EMA: Semaglutida como análogo de GLP-1","titel_en":"EMA: Semaglutida como análogo de GLP-1","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"Un análogo es una variante hecha en laboratorio de un péptido que ocurre naturalmente en la que se han intercambiado, añadido o eliminado aminoácidos individuales. Los investigadores utilizan tales cambios estructurales para estudiar propiedades como la estabilidad o el comportamiento de unión al receptor de manera dirigida. Un ejemplo es el semaglutida, un análogo de la hormona endógena GLP-1.","text_en":"Un análogo es una variante hecha en laboratorio de un péptido que ocurre naturalmente en la que se han intercambiado, añadido o eliminado aminoácidos individuales. Los investigadores utilizan tales cambios estructurales para estudiar propiedades como la estabilidad o el comportamiento de unión al receptor de manera dirigida. Un ejemplo es el semaglutida, un análogo de la hormona endógena GLP-1.","synonyme":["Análogos"],"synonyme_en":["Análogos"],"siehe":["peptid","fragment","agonist"]},{"slug":"antimikrobielles-peptid","begriff":"Péptidos antimicrobianos","begriff_en":"Péptidos antimicrobianos","kategorie":"klassen","kurz":"Los péptidos antimicrobianos son parte de la defensa inmunitaria innata, producidos en la piel y las membranas mucosas.","kurz_en":"Los péptidos antimicrobianos son parte de la defensa inmunitaria innata, producidos en la piel y las membranas mucosas.","quellen":[{"titel":"NCBI Bookshelf: Sistema inmunológico innato","titel_en":"NCBI Bookshelf: Sistema inmunológico innato","url":"https://www.ncbi.nlm.nih.gov/books/NBK459455/"}],"text":"Los péptidos antimicrobianos, también llamados AMPs o péptidos de defensa del huésped, son parte de la defensa inmunitaria innata. Son producidos por células de la piel y mucosas, así como por células inmunitarias, e insertan en las membranas de bacterias, hongos o virus. El grupo humano mejor conocido son las catelicidinas, cuya única forma humana activa es LL-37. Más allá de este mecanismo directo de membrana, los AMPs también se estudian como moléculas de señalización del sistema inmunológico.","text_en":"Los péptidos antimicrobianos, también llamados AMPs o péptidos de defensa del huésped, son parte de la defensa inmunitaria innata. Son producidos por células de la piel y mucosas, así como por células inmunitarias, e insertan en las membranas de bacterias, hongos o virus. El grupo humano mejor conocido son las catelicidinas, cuya única forma humana activa es LL-37. Más allá de este mecanismo directo de membrana, los AMPs también se estudian como moléculas de señalización del sistema inmunológico.","synonyme":["AMPs","Péptidos de defensa del huésped"],"synonyme_en":["AMPs","Péptidos de defensa del huésped"],"siehe":["protein","peptid"],"wirkstoffe":["ll-37"],"seiten":["peptid-1x1.html"]},{"slug":"aod-9604","begriff":"AOD-9604","begriff_en":"AOD-9604","kategorie":"wirkstoff","kurz":"Fragmento de hormona del crecimiento modificado investigado en estudios metabólicos.","kurz_en":"Fragmento de hormona del crecimiento modificado investigado en estudios metabólicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 11146367","titel_en":"PubMed: Publicación de investigación, PMID 11146367","url":"https://pubmed.ncbi.nlm.nih.gov/11146367/"}],"text":"El artículo original citado investiga AOD-9604 en ratas Zucker. Los hallazgos de este modelo animal no se pueden transferir directamente a humanos o productos vendidos por proveedores de investigación.","text_en":"El artículo original citado investiga AOD-9604 en ratas Zucker. Los hallazgos de este modelo animal no se pueden transferir directamente a humanos o productos vendidos por proveedores de investigación.","synonyme":["Medicamento antiobesidad 9604","Tyr-hGH Frag 177-191"],"synonyme_en":["Medicamento antiobesidad 9604","Tyr-hGH Frag 177-191"],"link":"wirkstoffe/aod-9604.html"},{"slug":"arzneimittel","begriff":"Producto medicinal","begriff_en":"Producto medicinal","kategorie":"recht","kurz":"Un producto medicinal se define legalmente como una sustancia destinada a tratar o prevenir enfermedades en humanos.","kurz_en":"Un producto medicinal se define legalmente como una sustancia destinada a tratar o prevenir enfermedades en humanos.","quellen":[{"titel":"Ley de Medicamentos alemana, sección 2: Definición de medicamentos","titel_en":"Ley de Medicamentos alemana, sección 2: Definición de medicamentos","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"}],"text":"La sección 2 de la Ley de Medicamentos de Alemania cubre sustancias basadas en su uso relacionado con la enfermedad previsto y ciertas funciones farmacológicas, inmunológicas o metabólicas. La clasificación es distinta de la autorización de comercialización. Una etiqueta RUO no excluye automáticamente el estado de producto medicinal.","text_en":"La sección 2 de la Ley de Medicamentos de Alemania cubre sustancias basadas en su uso relacionado con la enfermedad previsto y ciertas funciones farmacológicas, inmunológicas o metabólicas. La clasificación es distinta de la autorización de comercialización. Una etiqueta RUO no excluye automáticamente el estado de producto medicinal.","synonyme":["Medicamento"],"synonyme_en":["Medicamento"],"siehe":["ruo","zulassung","rezeptpflicht"],"seiten":["peptid-1x1.html"]},{"slug":"association","begriff":"Asociación (frente a causalidad)","begriff_en":"Asociación (frente a causalidad)","kategorie":"studien","kurz":"Dos cosas ocurren juntas. Eso por sí solo no demuestra que una cause la otra.","kurz_en":"Dos cosas ocurren juntas. Eso por sí solo no demuestra que una cause la otra.","quellen":[{"titel":"NLM MeSH: Causality","titel_en":"NLM MeSH: Causality","url":"https://www.ncbi.nlm.nih.gov/mesh/68015984"}],"text":"Una asociación significa que dos características aparecen juntas desde el punto de vista estadístico, como un hábito y un resultado de salud. Causalidad significa que una produce la otra. Los estudios observacionales suelen mostrar solo asociaciones, porque los factores de confusión, la dirección inversa o el azar pueden explicar el vínculo. Para establecer causa y efecto se necesitan pruebas adicionales, como los ensayos aleatorizados.","text_en":"Una asociación significa que dos características aparecen juntas desde el punto de vista estadístico, como un hábito y un resultado de salud. Causalidad significa que una produce la otra. Los estudios observacionales suelen mostrar solo asociaciones, porque los factores de confusión, la dirección inversa o el azar pueden explicar el vínculo. Para establecer causa y efecto se necesitan pruebas adicionales, como los ensayos aleatorizados.","synonyme":["Correlación","Causalidad"],"synonyme_en":["Correlación","Causalidad"],"siehe":["confounder","observational-study","rct"],"seiten":["studien.html"]},{"slug":"bakteriostatisches-wasser","begriff":"Agua bacteriostática","begriff_en":"Agua bacteriostática","kategorie":"handhabung","kurz":"El agua bacteriostática es agua estéril con un conservante, generalmente alcohol bencílico, para soluciones utilizadas más de una vez.","kurz_en":"El agua bacteriostática es agua estéril con un conservante, generalmente alcohol bencílico, para soluciones utilizadas más de una vez.","quellen":[{"titel":"DailyMed: Agua bacteriostática, composición","titel_en":"DailyMed: Agua bacteriostática, composición","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=87d6e9dc-fe3b-4593-ac9a-d7493d1959c7"}],"text":"Bacteriostático significa que el crecimiento bacteriano se inhibe. La composición es específica del producto; las preparaciones medicinales pueden contener alcohol bencílico. Esta descripción no verifica ni la compatibilidad con un péptido particular ni la seguridad de un producto comercial.","text_en":"Bacteriostático significa que el crecimiento bacteriano se inhibe. La composición es específica del producto; las preparaciones medicinales pueden contener alcohol bencílico. Esta descripción no verifica ni la compatibilidad con un péptido particular ni la seguridad de un producto comercial.","synonyme":["Agua BAC"],"synonyme_en":["Agua BAC"],"siehe":["steriles-wasser","rekonstitution","sterilitaet"]},{"slug":"observational-study","begriff":"Estudio observacional","begriff_en":"Estudio observacional","kategorie":"studien","kurz":"Estudio en el que las personas solo son observadas o se miden resultados, sin ninguna intervención como un tratamiento.","kurz_en":"Estudio en el que las personas solo son observadas o se miden resultados, sin ninguna intervención como un tratamiento.","quellen":[{"titel":"NCI: estudio observacional","titel_en":"NCI: estudio observacional","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/observational-study"}],"text":"En un estudio observacional, las personas son observadas o se miden los resultados sin que los investigadores intenten influir en el resultado, por ejemplo mediante un tratamiento. Los estudios de cohortes son un ejemplo. Como los grupos no se asignan al azar, los estudios observacionales pueden mostrar asociaciones, pero no pueden demostrar una causa.","text_en":"En un estudio observacional, las personas son observadas o se miden los resultados sin que los investigadores intenten influir en el resultado, por ejemplo mediante un tratamiento. Los estudios de cohortes son un ejemplo. Como los grupos no se asignan al azar, los estudios observacionales pueden mostrar asociaciones, pero no pueden demostrar una causa.","synonyme":["Estudios observacionales"],"synonyme_en":["Estudios observacionales"],"siehe":["cohort-study","association","rct"],"seiten":["studien.html"]},{"slug":"bioregulator","begriff":"Bioreguladores","begriff_en":"Bioreguladores","kategorie":"klassen","kurz":"Los bioreguladores son péptidos sintéticos muy cortos de dos a cuatro aminoácidos estudiados en sistemas orgánicos.","kurz_en":"Los bioreguladores son péptidos sintéticos muy cortos de dos a cuatro aminoácidos estudiados en sistemas orgánicos.","quellen":[{"titel":"Khavinson et al. (2003): Hipótesis de regulación génica","titel_en":"Khavinson et al. (2003): Hipótesis de regulación génica","url":"https://pubmed.ncbi.nlm.nih.gov/14666197/"}],"text":"En partes de la investigación de péptidos, este término describe secuencias cortas investigadas por su implicación en la regulación génica. No es una categoría regulatoria que establezca eficacia. Los hallazgos celulares individuales no establecen beneficios específicos de órganos ni extensión de la vida humana.","text_en":"En partes de la investigación de péptidos, este término describe secuencias cortas investigadas por su implicación en la regulación génica. No es una categoría regulatoria que establezca eficacia. Los hallazgos celulares individuales no establecen beneficios específicos de órganos ni extensión de la vida humana.","synonyme":["Bioreguladores de péptidos","Péptidos Khavinson"],"synonyme_en":["Bioreguladores de péptidos","Péptidos Khavinson"],"siehe":["oligopeptid","peptid"],"wirkstoffe":["epitalon"],"seiten":["peptid-1x1.html"]},{"slug":"bioverfuegbarkeit","begriff":"Biodisponibilidad","begriff_en":"Biodisponibilidad","kategorie":"grundlagen","kurz":"La proporción de una sustancia que llega a la sangre sin cambios y puede medirse allí.","kurz_en":"La proporción de una sustancia que llega a la sangre sin cambios y puede medirse allí.","quellen":[{"titel":"NCBI Bookshelf: Biodisponibilidad de fármacos","titel_en":"NCBI Bookshelf: Biodisponibilidad de fármacos","url":"https://www.ncbi.nlm.nih.gov/books/NBK557852/"}],"text":"La biodisponibilidad indica qué proporción de una sustancia administrada llega finalmente a la circulación sistémica sin cambios, medida como un porcentaje. Depende en parte de cuánto se descompone la sustancia por las enzimas, como a través de la proteólisis, en su camino por el cuerpo. Los estudios farmacocinéticos determinan la biodisponibilidad por separado para diferentes vías de administración.","text_en":"La biodisponibilidad indica qué proporción de una sustancia administrada llega finalmente a la circulación sistémica sin cambios, medida como un porcentaje. Depende en parte de cuánto se descompone la sustancia por las enzimas, como a través de la proteólisis, en su camino por el cuerpo. Los estudios farmacocinéticos determinan la biodisponibilidad por separado para diferentes vías de administración.","siehe":["halbwertszeit","proteolyse"]},{"slug":"blindtest","begriff":"Prueba ciega","begriff_en":"Prueba ciega","kategorie":"labor","kurz":"Prueba ciega: las personas involucradas no conocen detalles relevantes sobre la muestra.","kurz_en":"Prueba ciega: las personas involucradas no conocen detalles relevantes sobre la muestra.","quellen":[{"titel":"Karanicolas et al. (2010): Cegamiento y sus limitaciones","titel_en":"Karanicolas et al. (2010): Cegamiento y sus limitaciones","url":"https://pubmed.ncbi.nlm.nih.gov/20858381/"},{"titel":"Peptide Compass: Metodología y límites de verificación","titel_en":"Peptide Compass: Metodología y límites de verificación","url":"https://peptidkompass.com/es/methodik.html"}],"text":"En una prueba de laboratorio cegada, se retiene información sobre el origen de una muestra antes del análisis. Esto puede reducir el sesgo de expectativa pero no puede descartar error o sesgo. El muestreo, los métodos y la trazabilidad documentada siguen siendo importantes. Peptide Compass no realiza sus propias pruebas ciegas.","text_en":"En una prueba de laboratorio cegada, se retiene información sobre el origen de una muestra antes del análisis. Esto puede reducir el sesgo de expectativa pero no puede descartar error o sesgo. El muestreo, los métodos y la trazabilidad documentada siguen siendo importantes. Peptide Compass no realiza sus propias pruebas ciegas.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"bpc-157","begriff":"BPC-157","begriff_en":"BPC-157","kategorie":"wirkstoff","kurz":"Péptido sintético investigado en modelos preclínicos.","kurz_en":"Péptido sintético investigado en modelos preclínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 27847966","titel_en":"PubMed: Publicación de investigación, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"El estudio celular y animal enlazado investiga la formación de vasos sanguíneos y la señalización VEGFR2. Dichos hallazgos preclínicos no establecen eficacia o uso seguro en humanos.","text_en":"El estudio celular y animal enlazado investiga la formación de vasos sanguíneos y la señalización VEGFR2. Dichos hallazgos preclínicos no establecen eficacia o uso seguro en humanos.","synonyme":["Compuesto de Protección Corporal 157","PL 14736"],"synonyme_en":["Compuesto de Protección Corporal 157","PL 14736"],"link":"wirkstoffe/bpc-157.html"},{"slug":"cagrilintid","begriff":"Cagrilintida","begriff_en":"Cagrilintida","kategorie":"wirkstoff","kurz":"Análogo de amilina sintético investigado en investigación metabólica.","kurz_en":"Análogo de amilina sintético investigado en investigación metabólica.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 34288673","titel_en":"PubMed: Publicación de investigación, PMID 34288673","url":"https://pubmed.ncbi.nlm.nih.gov/34288673/"}],"text":"El documento de desarrollo citado describe la estructura y selección de un análogo de amilina de acción prolongada. Una medicina en investigación debe distinguirse de un producto químico de investigación vendido bajo el mismo nombre.","text_en":"El documento de desarrollo citado describe la estructura y selección de un análogo de amilina de acción prolongada. Una medicina en investigación debe distinguirse de un producto químico de investigación vendido bajo el mismo nombre.","synonyme":["AM833","NN9838"],"synonyme_en":["AM833","NN9838"],"link":"wirkstoffe/cagrilintid.html"},{"slug":"charge","begriff":"Lote","begriff_en":"Lote","kategorie":"labor","kurz":"Un lote es una única serie de producción con su propio número de lote, al que realmente se refiere el Certificado de Análisis.","kurz_en":"Un lote es una única serie de producción con su propio número de lote, al que realmente se refiere el Certificado de Análisis.","quellen":[{"titel":"ICH Q7: Fabricación, lotes y certificados de análisis","titel_en":"ICH Q7: Fabricación, lotes y certificados de análisis","url":"https://www.fda.gov/media/71518/download"}],"text":"El número de lote vincula un vial particular con el informe correspondiente, lo que hace que un resultado sea trazable. Un CoA sin referencia de lote clara no se puede vincular a un producto real y dice correspondientemente poco.","text_en":"El número de lote vincula un vial particular con el informe correspondiente, lo que hace que un resultado sea trazable. Un CoA sin referencia de lote clara no se puede vincular a un producto real y dice correspondientemente poco.","synonyme":["Lote","Lote de producción"],"synonyme_en":["Lote","Lote de producción"],"siehe":["coa","drittlabor"],"seiten":["charge-pruefen.html"]},{"slug":"chromatogramm","begriff":"Cromatograma","begriff_en":"Cromatograma","kategorie":"labor","kurz":"Registro gráfico de la separación cromatográfica, por ejemplo en HPLC.","kurz_en":"Registro gráfico de la separación cromatográfica, por ejemplo en HPLC.","quellen":[{"titel":"IUPAC Gold Book: Cromatograma","titel_en":"IUPAC Gold Book: Cromatograma","url":"https://goldbook.iupac.org/terms/view/C01071"}],"text":"Un cromatograma muestra la señal del detector durante la separación cromatográfica. Los picos pueden superponerse. Los porcentajes de área dependen del método y el detector y no son porcentajes de masa automáticos. Un cromatograma por sí solo no confirma la identidad del péptido.","text_en":"Un cromatograma muestra la señal del detector durante la separación cromatográfica. Los picos pueden superponerse. Los porcentajes de área dependen del método y el detector y no son porcentajes de masa automáticos. Un cromatograma por sí solo no confirma la identidad del péptido.","siehe":["hplc","reinheit"],"seiten":["peptid-1x1.html"]},{"slug":"cjc-1295","begriff":"CJC-1295","begriff_en":"CJC-1295","kategorie":"wirkstoff","kurz":"Análogo de GHRH sintético investigado en investigación endocrina.","kurz_en":"Análogo de GHRH sintético investigado en investigación endocrina.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 16352683","titel_en":"PubMed: Publicación de investigación, PMID 16352683","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"text":"El artículo enlazado investiga un análogo de GHRH de acción prolongada en adultos sanos. El compuesto estudiado debe distinguirse de formas modificadas de manera diferente ofrecidas bajo nombres comerciales similares.","text_en":"El artículo enlazado investiga un análogo de GHRH de acción prolongada en adultos sanos. El compuesto estudiado debe distinguirse de formas modificadas de manera diferente ofrecidas bajo nombres comerciales similares.","synonyme":["CJC-1295 con DAC","DAC:GRF"],"synonyme_en":["CJC-1295 con DAC","DAC:GRF"],"link":"wirkstoffe/cjc-1295.html"},{"slug":"coa","begriff":"CoA","begriff_en":"CoA","kategorie":"labor","kurz":"Un CoA es un informe vinculado a un lote específico, que enumera el número de lote, el método de prueba y valores como pureza o identidad.","kurz_en":"Un CoA es un informe vinculado a un lote específico, que enumera el número de lote, el método de prueba y valores como pureza o identidad.","quellen":[{"titel":"ICH Q7: Fabricación, lotes y certificados de análisis","titel_en":"ICH Q7: Fabricación, lotes y certificados de análisis","url":"https://www.fda.gov/media/71518/download"}],"langform":"Certificado de Análisis","langform_en":"Certificado de Análisis","text":"El valor de un CoA depende del número de lote, ya que solo este vincula un informe a un vial particular. Un CoA de muestra genérica sin vínculo a un lote real dice poco sobre el producto real. Las entradas comunes incluyen pureza, identidad y a veces un valor de endotoxina.","text_en":"El valor de un CoA depende del número de lote, ya que solo este vincula un informe a un vial particular. Un CoA de muestra genérica sin vínculo a un lote real dice poco sobre el producto real. Las entradas comunes incluyen pureza, identidad y a veces un valor de endotoxina.","synonyme":["Certificado de análisis","Informe de prueba"],"synonyme_en":["Certificado de análisis","Informe de prueba"],"siehe":["charge","reinheit","identitaet","drittlabor"],"seiten":["charge-pruefen.html","peptid-1x1.html"]},{"slug":"datenbasis","begriff":"Cobertura de evidencia","begriff_en":"Cobertura de evidencia","kategorie":"vergleich","kurz":"La cobertura de evidencia muestra cuántos de los cinco criterios de puntuación están documentados para un proveedor.","kurz_en":"La cobertura de evidencia muestra cuántos de los cinco criterios de puntuación están documentados para un proveedor.","quellen":[{"titel":"Peptide Compass: Nuestra metodología de comparación","titel_en":"Peptide Compass: Nuestra metodología de comparación","url":"https://peptidkompass.com/es/methodik.html"}],"text":"Debido a que los criterios faltantes se omiten del cálculo de la puntuación y los pesos restantes se redistribuyen, un único criterio documentado ya puede producir un valor alto. Por lo tanto, los proveedores con diferente cobertura de evidencia son solo parcialmente comparables. El número de criterios documentados se muestra junto a la puntuación.","text_en":"Debido a que los criterios faltantes se omiten del cálculo de la puntuación y los pesos restantes se redistribuyen, un único criterio documentado ya puede producir un valor alto. Por lo tanto, los proveedores con diferente cobertura de evidencia son solo parcialmente comparables. El número de criterios documentados se muestra junto a la puntuación.","siehe":["dokumentationsscore"],"seiten":["methodik.html"]},{"slug":"dihexa","begriff":"Dihexa","begriff_en":"Dihexa","kategorie":"wirkstoff","kurz":"Análogo de angiotensina IV sintético investigado en modelos preclínicos.","kurz_en":"Análogo de angiotensina IV sintético investigado en modelos preclínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 38489193","titel_en":"PubMed: Publicación de investigación, PMID 38489193","url":"https://pubmed.ncbi.nlm.nih.gov/38489193/"},{"titel":"PubMed: Expresión de preocupación sobre el artículo temprano","titel_en":"PubMed: Expresión de preocupación sobre el artículo temprano","url":"https://pubmed.ncbi.nlm.nih.gov/34551989/"}],"text":"Dihexa se investiga en modelos animales. El artículo temprano con PMID 23055539 tiene una Expresión de Preocupación y no se trata aquí como evidencia segura. El artículo vinculado adicional describe un modelo de rata y no establece el uso humano.","text_en":"Dihexa se investiga en modelos animales. El artículo temprano con PMID 23055539 tiene una Expresión de Preocupación y no se trata aquí como evidencia segura. El artículo vinculado adicional describe un modelo de rata y no establece el uso humano.","synonyme":["PNB-0408","N-Hexanoil-Tyr-Ile-(6)aminohexanamida"],"synonyme_en":["PNB-0408","N-Hexanoil-Tyr-Ile-(6)aminohexanamida"],"link":"wirkstoffe/dihexa.html"},{"slug":"dokumentationsscore","begriff":"Puntuación de documentación","begriff_en":"Puntuación de documentación","kategorie":"vergleich","kurz":"La puntuación de documentación muestra cuántas afirmaciones verificadas del proveedor están documentadas realmente.","kurz_en":"La puntuación de documentación muestra cuántas afirmaciones verificadas del proveedor están documentadas realmente.","quellen":[{"titel":"Peptide Compass: Nuestra metodología de comparación","titel_en":"Peptide Compass: Nuestra metodología de comparación","url":"https://peptidkompass.com/es/methodik.html"}],"text":"La metodología define cinco criterios ponderados. Actualmente, la documentación de laboratorio, la información legal y el envío contribuyen; el precio y el rango permanecen sin puntuar. Los criterios faltantes se omiten y los pesos restantes se normalizan. La puntuación no es un sello de calidad ni una evaluación de seguridad del producto.","text_en":"La metodología define cinco criterios ponderados. Actualmente, la documentación de laboratorio, la información legal y el envío contribuyen; el precio y el rango permanecen sin puntuar. Los criterios faltantes se omiten y los pesos restantes se normalizan. La puntuación no es un sello de calidad ni una evaluación de seguridad del producto.","siehe":["datenbasis","coa"],"seiten":["methodik.html"]},{"slug":"doppelblind","begriff":"Ensayo doble ciego","begriff_en":"Ensayo doble ciego","kategorie":"studien","kurz":"Un diseño de estudio donde ni los participantes ni el personal saben quién recibe la sustancia activa o el placebo. Reduce el sesgo inconsciente.","kurz_en":"Un diseño de estudio donde ni los participantes ni el personal saben quién recibe la sustancia activa o el placebo. Reduce el sesgo inconsciente.","quellen":[{"titel":"NCI: estudio doble ciego","titel_en":"NCI: estudio doble ciego","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/double-blind-study"}],"text":"Los participantes y los miembros del equipo del estudio cegados no saben las asignaciones de grupo. Esto puede reducir el sesgo de expectativa y evaluación. El cegamiento es una característica de calidad pero no excluye otros errores metodológicos.","text_en":"Los participantes y los miembros del equipo del estudio cegados no saben las asignaciones de grupo. Esto puede reducir el sesgo de expectativa y evaluación. El cegamiento es una característica de calidad pero no excluye otros errores metodológicos.","synonyme":["Doble ciego","Ciego doble"],"synonyme_en":["Doble ciego","Ciego doble"],"siehe":["rct","placebo"],"seiten":["studien.html"]},{"slug":"drittlabor","begriff":"Laboratorio de terceros","begriff_en":"Laboratorio de terceros","kategorie":"labor","kurz":"Un laboratorio de terceros es un laboratorio externo que prueba y documenta una muestra independientemente del fabricante o la tienda.","kurz_en":"Un laboratorio de terceros es un laboratorio externo que prueba y documenta una muestra independientemente del fabricante o la tienda.","quellen":[{"titel":"ISO/IEC 17025:2017: Competencia de los laboratorios de ensayo","titel_en":"ISO/IEC 17025:2017: Competencia de los laboratorios de ensayo","url":"https://www.iso.org/standard/66912.html"}],"text":"Si un CoA nombra un laboratorio externo, vale la pena verificar si el nombre es verificable en absoluto y si posee acreditación como ISO 17025. Una prueba ciega es una forma de verificar un resultado independientemente además de eso.","text_en":"Si un CoA nombra un laboratorio externo, vale la pena verificar si el nombre es verificable en absoluto y si posee acreditación como ISO 17025. Una prueba ciega es una forma de verificar un resultado independientemente además de eso.","synonyme":["Laboratorio externo"],"synonyme_en":["Laboratorio externo"],"siehe":["coa","iso-17025","blindtest"],"seiten":["methodik.html","charge-pruefen.html"]},{"slug":"dsip","begriff":"DSIP","begriff_en":"DSIP","kategorie":"wirkstoff","kurz":"Péptido inductor del sueño Delta, descrito originalmente en experimentos animales.","kurz_en":"Péptido inductor del sueño Delta, descrito originalmente en experimentos animales.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 265572","titel_en":"PubMed: Publicación de investigación, PMID 265572","url":"https://pubmed.ncbi.nlm.nih.gov/265572/"}],"text":"DSIP fue aislado y investigado experimentalmente en un estudio temprano en conejos. Su nombre refleja la hipótesis de investigación en ese momento. No establece un efecto de sueño fiable en humanos.","text_en":"DSIP fue aislado y investigado experimentalmente en un estudio temprano en conejos. Su nombre refleja la hipótesis de investigación en ese momento. No establece un efecto de sueño fiable en humanos.","synonyme":["Péptido Inductor de Sueño Delta","Péptido de Sueño Delta"],"synonyme_en":["Péptido Inductor de Sueño Delta","Péptido de Sueño Delta"],"link":"wirkstoffe/dsip.html"},{"slug":"ema","begriff":"EMA","begriff_en":"EMA","kategorie":"recht","kurz":"La EMA es la agencia de la UE que coordina y evalúa los procedimientos de autorización de comercialización centralizados.","kurz_en":"La EMA es la agencia de la UE que coordina y evalúa los procedimientos de autorización de comercialización centralizados.","quellen":[{"titel":"EMA: Decisiones de evaluación y autorización","titel_en":"EMA: Decisiones de evaluación y autorización","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"langform":"Agencia Europea de Medicamentos","langform_en":"Agencia Europea de Medicamentos","text":"La Agencia Europea de Medicamentos coordina la evaluación científica en el procedimiento de autorización centralizado de la UE y publica informes de evaluación. La Comisión Europea toma la decisión de autorización. Un informe de la EMA no es un certificado de prueba para productos vendidos por un proveedor de investigación.","text_en":"La Agencia Europea de Medicamentos coordina la evaluación científica en el procedimiento de autorización centralizado de la UE y publica informes de evaluación. La Comisión Europea toma la decisión de autorización. Un informe de la EMA no es un certificado de prueba para productos vendidos por un proveedor de investigación.","siehe":["zulassung","fda"]},{"slug":"endotoxin","begriff":"Endotoxina","begriff_en":"Endotoxina","kategorie":"labor","kurz":"Las endotoxinas son componentes de la pared celular bacteriana, y la cantidad en una muestra generalmente se indica en unidades por miligramo.","kurz_en":"Las endotoxinas son componentes de la pared celular bacteriana, y la cantidad en una muestra generalmente se indica en unidades por miligramo.","quellen":[{"titel":"FDA: Prueba de piregénos y endotoxinas","titel_en":"FDA: Prueba de piregénos y endotoxinas","url":"https://www.fda.gov/media/83477/download"}],"text":"Las endotoxinas bacterianas son componentes de bacterias Gram-negativas. Los resultados utilizan unidades de endotoxina con una cantidad de referencia indicada. Las pruebas incluyen métodos LAL convencionales y reactivos recombinantes. Las pruebas de endotoxinas, las pruebas de esterilidad y las pruebas de pureza química responden a diferentes preguntas.","text_en":"Las endotoxinas bacterianas son componentes de bacterias Gram-negativas. Los resultados utilizan unidades de endotoxina con una cantidad de referencia indicada. Las pruebas incluyen métodos LAL convencionales y reactivos recombinantes. Las pruebas de endotoxinas, las pruebas de esterilidad y las pruebas de pureza química responden a diferentes preguntas.","siehe":["sterilitaet","coa"],"seiten":["methodik.html"]},{"slug":"epitalon","begriff":"Epitalon","begriff_en":"Epitalon","kategorie":"wirkstoff","kurz":"Tetrapeptido sintético investigado en cultivos celulares por actividad de telomerasa.","kurz_en":"Tetrapeptido sintético investigado en cultivos celulares por actividad de telomerasa.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 12937682","titel_en":"PubMed: Publicación de investigación, PMID 12937682","url":"https://pubmed.ncbi.nlm.nih.gov/12937682/"}],"text":"El artículo citado investiga epithalon en cultivos celulares de fibroblastos humanos. Las observaciones de telomerasa en células aisladas no establecen la extensión de la vida humana.","text_en":"El artículo citado investiga epithalon en cultivos celulares de fibroblastos humanos. Las observaciones de telomerasa en células aisladas no establecen la extensión de la vida humana.","synonyme":["Epithalon","Tetrapeptido AEDG"],"synonyme_en":["Epithalon","Tetrapeptido AEDG"],"link":"wirkstoffe/epitalon.html"},{"slug":"fallbericht","begriff":"Informe de caso","begriff_en":"Informe de caso","kategorie":"studien","kurz":"Una descripción detallada de un caso único, a menudo inusual. Proporciona una pista temprana pero no evidencia estadística.","kurz_en":"Una descripción detallada de un caso único, a menudo inusual. Proporciona una pista temprana pero no evidencia estadística.","quellen":[{"titel":"NCI: informe de caso","titel_en":"NCI: informe de caso","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/case-report"}],"text":"Un informe de caso describe observaciones en una persona o un pequeño grupo de casos, a menudo una reacción inusual o un evento raro. Puede provocar más investigación, pero no tiene grupo de control ni análisis estadístico. Un informe de caso por sí solo no demuestra un efecto general.","text_en":"Un informe de caso describe observaciones en una persona o un pequeño grupo de casos, a menudo una reacción inusual o un evento raro. Puede provocar más investigación, pero no tiene grupo de control ni análisis estadístico. Un informe de caso por sí solo no demuestra un efecto general.","synonyme":["Informe de Caso"],"synonyme_en":["Informe de Caso"],"siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"fda","begriff":"FDA","begriff_en":"FDA","kategorie":"recht","kurz":"Agencia de EE. UU. responsable de regular medicamentos, alimentos y dispositivos médicos, entre otros productos.","kurz_en":"Agencia de EE. UU. responsable de regular medicamentos, alimentos y dispositivos médicos, entre otros productos.","quellen":[{"titel":"FDA: lo que hace y no aprueba la agencia","titel_en":"FDA: lo que hace y no aprueba la agencia","url":"https://www.fda.gov/consumers/consumer-updates/10-facts-about-what-fda-does-and-does-not-approve"}],"langform":"Administración de Alimentos y Medicamentos","langform_en":"Administración de Alimentos y Medicamentos","text":"La Administración de Alimentos y Medicamentos regula medicamentos, alimentos y dispositivos médicos, entre otros productos, en los Estados Unidos. No toda categoría de producto regulado recibe aprobación previa a la comercialización. La aprobación de la FDA concierne a un producto específico y no a la autorización de la UE.","text_en":"La Administración de Alimentos y Medicamentos regula medicamentos, alimentos y dispositivos médicos, entre otros productos, en los Estados Unidos. No toda categoría de producto regulado recibe aprobación previa a la comercialización. La aprobación de la FDA concierne a un producto específico y no a la autorización de la UE.","siehe":["zulassung","ema"]},{"slug":"fragment","begriff":"Fragmento","begriff_en":"Fragmento","kategorie":"grundlagen","kurz":"Una sección corta de un péptido o proteína endógeno más grande, reproducida sintéticamente.","kurz_en":"Una sección corta de un péptido o proteína endógeno más grande, reproducida sintéticamente.","quellen":[{"titel":"Purves et al.: neurotransmisores peptídicos","titel_en":"Purves et al.: neurotransmisores peptídicos","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Un fragmento cubre solo una sección de la cadena de aminoácidos original de un péptido o proteína, no la secuencia completa. Tales secuencias parciales se sintetizan para estudiar qué parte de una cadena es responsable de propiedades particulares, como la unión a receptores. Un ejemplo conocido es la timosina alfa-1, un fragmento de una proteína precursora más grande.","text_en":"Un fragmento cubre solo una sección de la cadena de aminoácidos original de un péptido o proteína, no la secuencia completa. Tales secuencias parciales se sintetizan para estudiar qué parte de una cadena es responsable de propiedades particulares, como la unión a receptores. Un ejemplo conocido es la timosina alfa-1, un fragmento de una proteína precursora más grande.","siehe":["peptid","analogon","sequenz"]},{"slug":"gegenion","begriff":"Ion contraión","begriff_en":"Ion contraión","kategorie":"labor","kurz":"Un ion contraión es el compañero salino de un péptido, generalmente trifluoroacetato (TFA) o acetato, sobrante de la fabricación.","kurz_en":"Un ion contraión es el compañero salino de un péptido, generalmente trifluoroacetato (TFA) o acetato, sobrante de la fabricación.","quellen":[{"titel":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","titel_en":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"Un ion contraión equilibra la carga eléctrica. Los contraiones pueden contribuir al peso de la muestra sin formar parte de la secuencia de aminoácidos del péptido.","text_en":"Un ion contraión equilibra la carga eléctrica. Los contraiones pueden contribuir al peso de la muestra sin formar parte de la secuencia de aminoácidos del péptido.","siehe":["peptidgehalt","reinheit"],"seiten":["methodik.html"]},{"slug":"ghk-cu","begriff":"GHK-Cu","begriff_en":"GHK-Cu","kategorie":"wirkstoff","kurz":"Complejo del tripéptido GHK y cobre investigado en varios modelos preclínicos.","kurz_en":"Complejo del tripéptido GHK y cobre investigado en varios modelos preclínicos.","quellen":[{"titel":"PubMed: publicación de investigación, PMID 40672369","titel_en":"PubMed: publicación de investigación, PMID 40672369","url":"https://pubmed.ncbi.nlm.nih.gov/40672369/"}],"text":"GHK significa glicil-histidil-lisina. El estudio vinculado investiga el complejo de cobre en un modelo experimental de colitis y ensayos celulares. No es evidencia clínica para el cuidado de la piel u otros usos.","text_en":"GHK significa glicil-histidil-lisina. El estudio vinculado investiga el complejo de cobre en un modelo experimental de colitis y ensayos celulares. No es evidencia clínica para el cuidado de la piel u otros usos.","synonyme":["Glicil-L-histidil-L-lisina cobre","Tripeptido de cobre-1"],"synonyme_en":["Glicil-L-histidil-L-lisina cobre","Tripeptido de cobre-1"],"link":"wirkstoffe/ghk-cu.html"},{"slug":"ghrh","begriff":"GHRH","begriff_en":"GHRH","kategorie":"klassen","kurz":"La GHRH es una hormona hipotalámica que activa la glándula pituitaria para que libere hormona del crecimiento.","kurz_en":"La GHRH es una hormona hipotalámica que activa la glándula pituitaria para que libere hormona del crecimiento.","quellen":[{"titel":"Teichman et al. (2006): Investigación sobre un análogo de GHRH","titel_en":"Teichman et al. (2006): Investigación sobre un análogo de GHRH","url":"https://pubmed.ncbi.nlm.nih.gov/16352683/"}],"langform":"Hormona liberadora de hormona del crecimiento","langform_en":"Hormona liberadora de hormona del crecimiento","text":"La hormona liberadora de hormona del crecimiento es un péptido hipotalámico que viaja a través del sistema portal pituitario hasta la glándula pituitaria, donde activa la liberación de hormona del crecimiento desde las células somatotrofos. Forma parte del eje de la hormona del crecimiento y es la contraparte del inhibidor propio del cuerpo, la somatostatina. Varios análogos sintéticos de GHRH se unen al mismo receptor y se estudian o utilizan en este contexto.","text_en":"La hormona liberadora de hormona del crecimiento es un péptido hipotalámico que viaja a través del sistema portal pituitario hasta la glándula pituitaria, donde activa la liberación de hormona del crecimiento desde las células somatotrofos. Forma parte del eje de la hormona del crecimiento y es la contraparte del inhibidor propio del cuerpo, la somatostatina. Varios análogos sintéticos de GHRH se unen al mismo receptor y se estudian o utilizan en este contexto.","synonyme":["Somatoliberina"],"synonyme_en":["Somatoliberina"],"siehe":["ghrp","wachstumshormon","rezeptor"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin"],"seiten":["peptid-1x1.html"]},{"slug":"ghrp","begriff":"GHRP","begriff_en":"GHRP","kategorie":"klassen","kurz":"Los GHRP son péptidos sintéticos que activan la liberación de hormona del crecimiento a través del receptor de la grelina.","kurz_en":"Los GHRP son péptidos sintéticos que activan la liberación de hormona del crecimiento a través del receptor de la grelina.","quellen":[{"titel":"Raun et al. (1998): Implicación del receptor en los GHRP","titel_en":"Raun et al. (1998): Implicación del receptor en los GHRP","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"langform":"Péptido liberador de hormona del crecimiento","langform_en":"Péptido liberador de hormona del crecimiento","text":"Los péptidos liberadores de hormona del crecimiento son una clase de péptidos sintéticos que se unen al receptor de la grelina (GHS-R) para activar la liberación de hormona del crecimiento desde la glándula pituitaria. A diferencia de los análogos de GHRH, utilizan una vía de señalización separada y a menudo se combinan con análogos de GHRH en investigación. El receptor de la grelina también está involucrado en la regulación del hambre y el apetito.","text_en":"Los péptidos liberadores de hormona del crecimiento son una clase de péptidos sintéticos que se unen al receptor de la grelina (GHS-R) para activar la liberación de hormona del crecimiento desde la glándula pituitaria. A diferencia de los análogos de GHRH, utilizan una vía de señalización separada y a menudo se combinan con análogos de GHRH en investigación. El receptor de la grelina también está involucrado en la regulación del hambre y el apetito.","synonyme":["Secretagogos de GH","Secretagogos de hormona del crecimiento"],"synonyme_en":["Secretagogos de GH","Secretagogos de hormona del crecimiento"],"siehe":["ghrh","wachstumshormon","rezeptor"],"wirkstoffe":["ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"gip","begriff":"GIP","begriff_en":"GIP","kategorie":"klassen","kurz":"La GIP es una hormona intestinal que regula la liberación de insulina después de comidas ricas en carbohidratos.","kurz_en":"La GIP es una hormona intestinal que regula la liberación de insulina después de comidas ricas en carbohidratos.","quellen":[{"titel":"NIDDK: Fundamentos de la investigación de incretinas","titel_en":"NIDDK: Fundamentos de la investigación de incretinas","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Polipeptido insulinotrópico dependiente de la glucosa","langform_en":"Polipeptido insulinotrópico dependiente de la glucosa","text":"El polipeptido insulinotrópico dependiente de la glucosa es la segunda hormona incretina principal junto con GLP-1. Las células K en el intestino delgado superior lo liberan después de comer, y se une al receptor de la GIP para regular la liberación de insulina. También está involucrado en el metabolismo de la grasa. Varios compuestos más nuevos para la diabetes y la obesidad combinan la GIP con agonismo del receptor de GLP-1.","text_en":"El polipeptido insulinotrópico dependiente de la glucosa es la segunda hormona incretina principal junto con GLP-1. Las células K en el intestino delgado superior lo liberan después de comer, y se une al receptor de la GIP para regular la liberación de insulina. También está involucrado en el metabolismo de la grasa. Varios compuestos más nuevos para la diabetes y la obesidad combinan la GIP con agonismo del receptor de GLP-1.","siehe":["glp-1","inkretin","rezeptor"],"wirkstoffe":["tirzepatid","retatrutid"],"seiten":["peptid-1x1.html"]},{"slug":"glp-1","begriff":"GLP-1","begriff_en":"GLP-1","kategorie":"klassen","kurz":"La GLP-1 es una hormona intestinal liberada después de comer que regula la liberación de insulina.","kurz_en":"La GLP-1 es una hormona intestinal liberada después de comer que regula la liberación de insulina.","quellen":[{"titel":"NIDDK: Fundamentos de la investigación de incretinas","titel_en":"NIDDK: Fundamentos de la investigación de incretinas","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"langform":"Péptido similar al glucagón 1","langform_en":"Péptido similar al glucagón 1","text":"El péptido similar al glucagón 1 es una hormona incretina liberada por las células L en el intestino delgado después de comer. Se une al receptor GLP-1, regula la liberación de insulina, ralentiza el vaciado gástrico y está involucrado en la señalización de saciedad en el cerebro. Varios agonistas del receptor GLP-1 sintéticos se dirigen a este sistema, y algunos están aprobados como medicamentos.","text_en":"El péptido similar al glucagón 1 es una hormona incretina liberada por las células L en el intestino delgado después de comer. Se une al receptor GLP-1, regula la liberación de insulina, ralentiza el vaciado gástrico y está involucrado en la señalización de saciedad en el cerebro. Varios agonistas del receptor GLP-1 sintéticos se dirigen a este sistema, y algunos están aprobados como medicamentos.","synonyme":["Péptido similar al glucagón-1"],"synonyme_en":["Péptido similar al glucagón-1"],"siehe":["gip","inkretin","rezeptor","agonist"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"gmp","begriff":"GMP","begriff_en":"GMP","kategorie":"recht","kurz":"GMP es un estándar de calidad reconocido para la fabricación de productos medicinales y bienes similares.","kurz_en":"GMP es un estándar de calidad reconocido para la fabricación de productos medicinales y bienes similares.","quellen":[{"titel":"ICH Q7: Fabricación, lotes y certificados de análisis","titel_en":"ICH Q7: Fabricación, lotes y certificados de análisis","url":"https://www.fda.gov/media/71518/download"}],"langform":"Buena Práctica de Fabricación","langform_en":"Buena Práctica de Fabricación","text":"La Buena Práctica de Fabricación cubre los requisitos para instalaciones, procesos, documentación y trazabilidad en la producción. La GMP es obligatoria principalmente para productos medicinales autorizados. Una declaración de GMP de un fabricante no reemplaza la evidencia independiente como un CoA público y se aplica solo en la medida en que esté documentado.","text_en":"La Buena Práctica de Fabricación cubre los requisitos para instalaciones, procesos, documentación y trazabilidad en la producción. La GMP es obligatoria principalmente para productos medicinales autorizados. Una declaración de GMP de un fabricante no reemplaza la evidencia independiente como un CoA público y se aplica solo en la medida en que esté documentado.","siehe":["zulassung","coa"],"seiten":["methodik.html"]},{"slug":"halbwertszeit","begriff":"Vida media","begriff_en":"Vida media","kategorie":"grundlagen","kurz":"El tiempo que tarda la concentración de una sustancia en el cuerpo en reducirse a la mitad.","kurz_en":"El tiempo que tarda la concentración de una sustancia en el cuerpo en reducirse a la mitad.","quellen":[{"titel":"NCBI Bookshelf: Farmacocinética","titel_en":"NCBI Bookshelf: Farmacocinética","url":"https://www.ncbi.nlm.nih.gov/books/NBK557744/"}],"text":"La vida media describe cuánto tiempo se tarda en que la concentración sanguínea de un péptido caiga a la mitad de su valor inicial. Se mide en estudios farmacocinéticos y varía considerablemente entre péptidos individuales, dependiendo en parte de la rapidez con la que las enzimas endógenas descomponen la cadena a través de la proteólisis. Una vida media más corta significa una descomposición más rápida en comparación con una más larga.","text_en":"La vida media describe cuánto tiempo se tarda en que la concentración sanguínea de un péptido caiga a la mitad de su valor inicial. Se mide en estudios farmacocinéticos y varía considerablemente entre péptidos individuales, dependiendo en parte de la rapidez con la que las enzimas endógenas descomponen la cadena a través de la proteólisis. Una vida media más corta significa una descomposición más rápida en comparación con una más larga.","siehe":["proteolyse","bioverfuegbarkeit"]},{"slug":"hazard-ratio","begriff":"Razón de riesgos instantáneos (hazard ratio)","begriff_en":"Razón de riesgos instantáneos (hazard ratio)","kategorie":"studien","kurz":"Medida que compara la frecuencia con que ocurre un evento en dos grupos a lo largo del tiempo. Un valor de 1 significa que no hay diferencia.","kurz_en":"Medida que compara la frecuencia con que ocurre un evento en dos grupos a lo largo del tiempo. Un valor de 1 significa que no hay diferencia.","quellen":[{"titel":"NCI: hazard ratio","titel_en":"NCI: hazard ratio","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/hazard-ratio"}],"text":"La razón de riesgos instantáneos (hazard ratio, HR) compara con qué frecuencia ocurre un evento, como la progresión de una enfermedad, en un grupo en relación con otro a lo largo del tiempo. Un valor de 1 significa que no hay diferencia; los valores superiores o inferiores a 1 muestran en qué grupo el evento fue más frecuente. No dice nada sobre el riesgo absoluto y se lee junto con un intervalo de confianza.","text_en":"La razón de riesgos instantáneos (hazard ratio, HR) compara con qué frecuencia ocurre un evento, como la progresión de una enfermedad, en un grupo en relación con otro a lo largo del tiempo. Un valor de 1 significa que no hay diferencia; los valores superiores o inferiores a 1 muestran en qué grupo el evento fue más frecuente. No dice nada sobre el riesgo absoluto y se lee junto con un intervalo de confianza.","synonyme":["HR"],"synonyme_en":["HR"],"siehe":["confidence-interval","cohort-study","rct"],"seiten":["studien.html"]},{"slug":"hexarelin","begriff":"Hexarelin","begriff_en":"Hexarelin","kategorie":"wirkstoff","kurz":"Péptido sintético investigado en estudios del eje de la hormona del crecimiento.","kurz_en":"Péptido sintético investigado en estudios del eje de la hormona del crecimiento.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 7910650","titel_en":"PubMed: Publicación de investigación, PMID 7910650","url":"https://pubmed.ncbi.nlm.nih.gov/7910650/"}],"text":"El artículo original citado describe la hexarelina como un péptido sintético e investiga la liberación de hormona del crecimiento en ratas. Tales hallazgos de modelo no establecen un uso humano seguro.","text_en":"El artículo original citado describe la hexarelina como un péptido sintético e investiga la liberación de hormona del crecimiento en ratas. Tales hallazgos de modelo no establecen un uso humano seguro.","link":"wirkstoffe/hexarelin.html"},{"slug":"hplc","begriff":"HPLC","begriff_en":"HPLC","kategorie":"labor","kurz":"HPLC es el método analítico estándar utilizado para determinar la pureza de una muestra de péptido como porcentaje.","kurz_en":"HPLC es el método analítico estándar utilizado para determinar la pureza de una muestra de péptido como porcentaje.","quellen":[{"titel":"FDA: Análisis de mezclas complejas y péptidos","titel_en":"FDA: Análisis de mezclas complejas y péptidos","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"langform":"Cromatografía líquida de alta resolución","langform_en":"Cromatografía líquida de alta resolución","text":"El método separa una muestra en sus componentes y mide cada uno, produciendo un cromatograma con un pico por componente. El área del pico principal da el valor de pureza declarado. La HPLC por sí sola no dice nada sobre la identidad, eso requiere también espectrometría de masas.","text_en":"El método separa una muestra en sus componentes y mide cada uno, produciendo un cromatograma con un pico por componente. El área del pico principal da el valor de pureza declarado. La HPLC por sí sola no dice nada sobre la identidad, eso requiere también espectrometría de masas.","synonyme":["Cromatografía líquida de alta resolución"],"synonyme_en":["Cromatografía líquida de alta resolución"],"siehe":["reinheit","chromatogramm","massenspektrometrie"],"seiten":["methodik.html","peptid-1x1.html"]},{"slug":"hwg","begriff":"HWG","begriff_en":"HWG","kategorie":"recht","kurz":"La HWG regula la publicidad de productos medicinales y métodos terapéuticos al público en Alemania.","kurz_en":"La HWG regula la publicidad de productos medicinales y métodos terapéuticos al público en Alemania.","quellen":[{"titel":"Ley alemana sobre publicidad en el sistema de salud, texto oficial","titel_en":"Ley alemana sobre publicidad en el sistema de salud, texto oficial","url":"https://www.gesetze-im-internet.de/heilmwerbg/"}],"langform":"Ley sobre publicidad de productos terapéuticos","langform_en":"Ley sobre publicidad de productos terapéuticos","text":"La Ley alemana sobre publicidad de productos terapéuticos restringe cómo se pueden describir públicamente los medicamentos y los métodos de tratamiento, incluidas las afirmaciones sobre enfermedades o uso humano. Por esta razón, Peptide Compass describe las sustancias solo en términos de hallazgos de investigación y no hace declaraciones sobre un efecto en el cuerpo del lector.","text_en":"La Ley alemana sobre publicidad de productos terapéuticos restringe cómo se pueden describir públicamente los medicamentos y los métodos de tratamiento, incluidas las afirmaciones sobre enfermedades o uso humano. Por esta razón, Peptide Compass describe las sustancias solo en términos de hallazgos de investigación y no hace declaraciones sobre un efecto en el cuerpo del lector.","siehe":["arzneimittel"],"seiten":["methodik.html"]},{"slug":"identitaet","begriff":"Identidad","begriff_en":"Identidad","kategorie":"labor","kurz":"Identidad, confirmada por espectrometría de masas, verifica que una muestra contiene realmente el péptido indicado.","kurz_en":"Identidad, confirmada por espectrometría de masas, verifica que una muestra contiene realmente el péptido indicado.","quellen":[{"titel":"FDA: Análisis de mezclas complejas y péptidos","titel_en":"FDA: Análisis de mezclas complejas y péptidos","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"Generalmente se muestra mediante LC-MS, una combinación de cromatografía líquida y espectrometría de masas que mide el peso molecular. Pureza e identidad son dos cifras separadas, y un Certificado de Análisis completo enumera ambas. La pureza por sí sola no demuestra qué molécula está realmente presente.","text_en":"Generalmente se muestra mediante LC-MS, una combinación de cromatografía líquida y espectrometría de masas que mide el peso molecular. Pureza e identidad son dos cifras separadas, y un Certificado de Análisis completo enumera ambas. La pureza por sí sola no demuestra qué molécula está realmente presente.","siehe":["massenspektrometrie","reinheit","coa"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1","begriff":"IGF-1","begriff_en":"IGF-1","kategorie":"klassen","kurz":"El IGF-1 es una hormona producida principalmente en el hígado en respuesta a la hormona del crecimiento.","kurz_en":"El IGF-1 es una hormona producida principalmente en el hígado en respuesta a la hormona del crecimiento.","quellen":[{"titel":"NIDDK: Hormona del crecimiento e IGF-1","titel_en":"NIDDK: Hormona del crecimiento e IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Factor de crecimiento similar a la insulina 1","langform_en":"Factor de crecimiento similar a la insulina 1","text":"El factor de crecimiento similar a la insulina 1 se produce principalmente en el hígado, desencadenado por la unión de la hormona del crecimiento a las células hepáticas, y circula en la sangre en gran parte unido a proteínas transportadoras. Se une al receptor de IGF-1 y media gran parte del efecto de la hormona del crecimiento en el músculo, el hueso y el tejido conectivo. Se utiliza un análogo de IGF-1 con una vida media extendida en investigación como herramienta independiente, independientemente de la regulación del cuerpo a través de la hormona del crecimiento.","text_en":"El factor de crecimiento similar a la insulina 1 se produce principalmente en el hígado, desencadenado por la unión de la hormona del crecimiento a las células hepáticas, y circula en la sangre en gran parte unido a proteínas transportadoras. Se une al receptor de IGF-1 y media gran parte del efecto de la hormona del crecimiento en el músculo, el hueso y el tejido conectivo. Se utiliza un análogo de IGF-1 con una vida media extendida en investigación como herramienta independiente, independientemente de la regulación del cuerpo a través de la hormona del crecimiento.","synonyme":["Somatomedin C"],"synonyme_en":["Somatomedin C"],"siehe":["wachstumshormon","ghrh","rezeptor"],"wirkstoffe":["igf-1-lr3"],"seiten":["peptid-1x1.html"]},{"slug":"igf-1-lr3","begriff":"IGF-1 LR3","begriff_en":"IGF-1 LR3","kategorie":"wirkstoff","kurz":"Análogo modificado de IGF-1 investigado en modelos preclínicos.","kurz_en":"Análogo modificado de IGF-1 investigado en modelos preclínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 7561636","titel_en":"PubMed: Publicación de investigación, PMID 7561636","url":"https://pubmed.ncbi.nlm.nih.gov/7561636/"}],"text":"El artículo citado investiga Long R3 IGF-I en cobayas y describe una afinidad reducida por las proteínas que se unen al IGF. Los hallazgos para esta forma modificada no son intercambiables con los hallazgos para el IGF-1 endógeno.","text_en":"El artículo citado investiga Long R3 IGF-I en cobayas y describe una afinidad reducida por las proteínas que se unen al IGF. Los hallazgos para esta forma modificada no son intercambiables con los hallazgos para el IGF-1 endógeno.","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"synonyme_en":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"link":"wirkstoffe/igf-1-lr3.html"},{"slug":"in-vitro","begriff":"In vitro","begriff_en":"In vitro","kategorie":"studien","kurz":"Una prueba fuera de un organismo vivo, generalmente en cultivos celulares. No dice nada sobre un efecto en humanos.","kurz_en":"Una prueba fuera de un organismo vivo, generalmente en cultivos celulares. No dice nada sobre un efecto en humanos.","quellen":[{"titel":"NCI: in vitro","titel_en":"NCI: in vitro","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vitro"}],"text":"Los estudios in vitro examinan células o moléculas aisladas en un entorno controlado como una placa de Petri. Pueden mostrar efectos bioquímicos tempranos, pero el contexto celular no reemplaza a un organismo completo. Este tipo de datos cuenta como investigación de laboratorio y no se traduce a humanos.","text_en":"Los estudios in vitro examinan células o moléculas aisladas en un entorno controlado como una placa de Petri. Pueden mostrar efectos bioquímicos tempranos, pero el contexto celular no reemplaza a un organismo completo. Este tipo de datos cuenta como investigación de laboratorio y no se traduce a humanos.","synonyme":["in vitro"],"synonyme_en":["in vitro"],"siehe":["in-vivo","praeklinisch","tiermodell"],"seiten":["studien.html"]},{"slug":"in-vivo","begriff":"In vivo","begriff_en":"In vivo","kategorie":"studien","kurz":"Una investigación en un organismo vivo. El término por sí solo no distingue datos animales de humanos.","kurz_en":"Una investigación en un organismo vivo. El término por sí solo no distingue datos animales de humanos.","quellen":[{"titel":"NCI: in vivo","titel_en":"NCI: in vivo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/in-vivo"}],"text":"In vivo significa que una investigación tiene lugar en un organismo vivo. Puede ser un animal o un humano. Por lo tanto, los hallazgos de la investigación deben identificar el modelo estudiado. Los resultados animales no se pueden transferir directamente a humanos.","text_en":"In vivo significa que una investigación tiene lugar en un organismo vivo. Puede ser un animal o un humano. Por lo tanto, los hallazgos de la investigación deben identificar el modelo estudiado. Los resultados animales no se pueden transferir directamente a humanos.","synonyme":["in vivo"],"synonyme_en":["in vivo"],"siehe":["in-vitro","tiermodell","praeklinisch"],"seiten":["studien.html"]},{"slug":"inkretin","begriff":"Incretina","begriff_en":"Incretina","kategorie":"klassen","kurz":"Las incretinas son hormonas intestinales liberadas después de comer que están involucradas en la regulación de la liberación de insulina.","kurz_en":"Las incretinas son hormonas intestinales liberadas después de comer que están involucradas en la regulación de la liberación de insulina.","quellen":[{"titel":"NIDDK: Fundamentos de la investigación de incretinas","titel_en":"NIDDK: Fundamentos de la investigación de incretinas","url":"https://www.niddk.nih.gov/news/archive/2021/story-discovery-medications-diabetes-obesity-emerged-research-pancreatic-hormone"}],"text":"Las incretinas son una clase de hormonas del intestino que incluye GLP-1 y GIP. Se liberan de células intestinales especializadas después de comer y se unen a sus propios receptores en las células beta pancreáticas. A través de este mecanismo, la liberación de insulina después de la ingesta oral de glucosa es mayor que después de una dosis intravenosa de la misma cantidad, un efecto conocido como el efecto incretina. Varios medicamentos aprobados e investigacionales imitan esta vía.","text_en":"Las incretinas son una clase de hormonas del intestino que incluye GLP-1 y GIP. Se liberan de células intestinales especializadas después de comer y se unen a sus propios receptores en las células beta pancreáticas. A través de este mecanismo, la liberación de insulina después de la ingesta oral de glucosa es mayor que después de una dosis intravenosa de la misma cantidad, un efecto conocido como el efecto incretina. Varios medicamentos aprobados e investigacionales imitan esta vía.","synonyme":["hormonas incretinas"],"synonyme_en":["hormonas incretinas"],"siehe":["glp-1","gip","peptidhormon","rezeptor"],"wirkstoffe":["semaglutid","tirzepatid","retatrutid","survodutid"],"seiten":["peptid-1x1.html"]},{"slug":"ipamorelin","begriff":"Ipamorelina","begriff_en":"Ipamorelina","kategorie":"wirkstoff","kurz":"Penta-péptido sintético investigado en estudios de liberación de hormona del crecimiento.","kurz_en":"Penta-péptido sintético investigado en estudios de liberación de hormona del crecimiento.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 9849822","titel_en":"PubMed: Publicación de investigación, PMID 9849822","url":"https://pubmed.ncbi.nlm.nih.gov/9849822/"}],"text":"El artículo de desarrollo describe un pentapéptido e investiga la participación del receptor y la liberación de hormona en modelos celulares y animales. Esos hallazgos no se pueden transferir generalmente a humanos.","text_en":"El artículo de desarrollo describe un pentapéptido e investiga la participación del receptor y la liberación de hormona en modelos celulares y animales. Esos hallazgos no se pueden transferir generalmente a humanos.","synonyme":["NNC 26-0161"],"synonyme_en":["NNC 26-0161"],"link":"wirkstoffe/ipamorelin.html"},{"slug":"iso-17025","begriff":"ISO 17025","begriff_en":"ISO 17025","kategorie":"labor","kurz":"ISO 17025 es la norma internacional para la competencia técnica de los laboratorios de ensayo y calibración.","kurz_en":"ISO 17025 es la norma internacional para la competencia técnica de los laboratorios de ensayo y calibración.","quellen":[{"titel":"ISO/IEC 17025:2017: Competencia de los laboratorios de ensayo","titel_en":"ISO/IEC 17025:2017: Competencia de los laboratorios de ensayo","url":"https://www.iso.org/standard/66912.html"}],"langform":"ISO/IEC 17025","langform_en":"ISO/IEC 17025","text":"La acreditación bajo esta norma significa que los procedimientos, equipos y personal de un laboratorio fueron evaluados de forma independiente. Es un marcador de calidad para el laboratorio en sí, no una garantía para cualquier resultado de CoA específico.","text_en":"La acreditación bajo esta norma significa que los procedimientos, equipos y personal de un laboratorio fueron evaluados de forma independiente. Es un marcador de calidad para el laboratorio en sí, no una garantía para cualquier resultado de CoA específico.","siehe":["drittlabor","coa"],"seiten":["methodik.html"]},{"slug":"internationale-einheit","begriff":"UI","begriff_en":"UI","kategorie":"handhabung","kurz":"La Unidad Internacional mide la potencia biológica de una sustancia frente a un estándar de referencia, no su peso.","kurz_en":"La Unidad Internacional mide la potencia biológica de una sustancia frente a un estándar de referencia, no su peso.","quellen":[{"titel":"OMS: Estándares de referencia biológicos","titel_en":"OMS: Estándares de referencia biológicos","url":"https://www.who.int/activities/providing-international-biological-reference-standards"}],"langform":"Unidad Internacional","langform_en":"Unidad Internacional","text":"Para sustancias como la hormona del crecimiento, el peso por sí solo no describe el contenido de manera significativa, porque diferentes lotes pueden variar en pureza al mismo peso. La Unidad Internacional establece el contenido en relación con una preparación de referencia OMS definida. Por lo tanto, un miligramo de una hormona no es automáticamente igual al mismo número de unidades que un miligramo de una preparación diferente.","text_en":"Para sustancias como la hormona del crecimiento, el peso por sí solo no describe el contenido de manera significativa, porque diferentes lotes pueden variar en pureza al mismo peso. La Unidad Internacional establece el contenido en relación con una preparación de referencia OMS definida. Por lo tanto, un miligramo de una hormona no es automáticamente igual al mismo número de unidades que un miligramo de una preparación diferente.","synonyme":["UI"],"synonyme_en":["UI"],"siehe":["milligramm-mikrogramm","wachstumshormon"]},{"slug":"kisspeptin","begriff":"Kisspeptina-10","begriff_en":"Kisspeptina-10","kategorie":"wirkstoff","kurz":"Familia de péptidos investigada en investigación endocrina; este catálogo se centra en kisspeptina-10.","kurz_en":"Familia de péptidos investigada en investigación endocrina; este catálogo se centra en kisspeptina-10.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 21632807","titel_en":"PubMed: Publicación de investigación, PMID 21632807","url":"https://pubmed.ncbi.nlm.nih.gov/21632807/"}],"text":"El estudio citado investiga kisspeptina-10 en hombres. Otras isoformas como kisspeptina-54 deben considerarse por separado. El término paraguas kisspeptina no especifica completamente la forma estudiada.","text_en":"El estudio citado investiga kisspeptina-10 en hombres. Otras isoformas como kisspeptina-54 deben considerarse por separado. El término paraguas kisspeptina no especifica completamente la forma estudiada.","synonyme":["Metastin (45-54)","KP-10"],"synonyme_en":["Metastin (45-54)","KP-10"],"link":"wirkstoffe/kisspeptin.html"},{"slug":"klinische-studie","begriff":"Ensayo clínico","begriff_en":"Ensayo clínico","kategorie":"studien","kurz":"Un estudio en participantes humanos, generalmente estructurado en fases I a III. El tipo de estudio más informativo para humanos.","kurz_en":"Un estudio en participantes humanos, generalmente estructurado en fases I a III. El tipo de estudio más informativo para humanos.","quellen":[{"titel":"NCI: ensayo clínico","titel_en":"NCI: ensayo clínico","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/clinical-trial"}],"text":"Un estudio clínico investiga una pregunta médica que involucra a personas. Los estudios difieren en tamaño, grupos de comparación, cegamiento y resultados medidos. Estas características ayudan a determinar cuán fiable es un resultado. El registro o publicación de un estudio por sí solo no establece aprobación ni la calidad de un producto comercial.","text_en":"Un estudio clínico investiga una pregunta médica que involucra a personas. Los estudios difieren en tamaño, grupos de comparación, cegamiento y resultados medidos. Estas características ayudan a determinar cuán fiable es un resultado. El registro o publicación de un estudio por sí solo no establece aprobación ni la calidad de un producto comercial.","synonyme":["Estudio clínico"],"synonyme_en":["Estudio clínico"],"siehe":["studienphasen","rct","placebo","Ciego doble"],"seiten":["studien.html"]},{"slug":"cohort-study","begriff":"Estudio de cohortes","begriff_en":"Estudio de cohortes","kategorie":"studien","kurz":"Estudio observacional que sigue a lo largo del tiempo a grupos que difieren en una característica y compara un resultado.","kurz_en":"Estudio observacional que sigue a lo largo del tiempo a grupos que difieren en una característica y compara un resultado.","quellen":[{"titel":"NCI: estudio de cohortes","titel_en":"NCI: estudio de cohortes","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/cohort-study"}],"text":"En un estudio de cohortes, grupos de personas que difieren en una característica (por ejemplo, fumar o no fumar) se siguen durante un período y se compara un resultado determinado. Los investigadores no intervienen. Estos estudios muestran asociaciones, no causa y efecto, porque los grupos también pueden diferir en otros aspectos.","text_en":"En un estudio de cohortes, grupos de personas que difieren en una característica (por ejemplo, fumar o no fumar) se siguen durante un período y se compara un resultado determinado. Los investigadores no intervienen. Estos estudios muestran asociaciones, no causa y efecto, porque los grupos también pueden diferir en otros aspectos.","synonyme":["Estudios de cohortes"],"synonyme_en":["Estudios de cohortes"],"siehe":["observational-study","association","confounder"],"seiten":["studien.html"]},{"slug":"confidence-interval","begriff":"Intervalo de confianza","begriff_en":"Intervalo de confianza","kategorie":"studien","kurz":"Rango de valores construido para incluir el valor verdadero con una probabilidad determinada, normalmente del 95 %.","kurz_en":"Rango de valores construido para incluir el valor verdadero con una probabilidad determinada, normalmente del 95 %.","quellen":[{"titel":"NLM MeSH: Confidence Intervals","titel_en":"NLM MeSH: Confidence Intervals","url":"https://www.ncbi.nlm.nih.gov/mesh/68016001"}],"text":"Un intervalo de confianza (IC) es un rango de valores construido de modo que incluya el valor verdadero de una magnitud, como una tasa o una razón de riesgos instantáneos, con una probabilidad determinada, normalmente del 95 %. Un intervalo estrecho sugiere una estimación más precisa. Si el intervalo de una razón de riesgos instantáneos incluye 1, una diferencia entre los grupos no está establecida estadísticamente.","text_en":"Un intervalo de confianza (IC) es un rango de valores construido de modo que incluya el valor verdadero de una magnitud, como una tasa o una razón de riesgos instantáneos, con una probabilidad determinada, normalmente del 95 %. Un intervalo estrecho sugiere una estimación más precisa. Si el intervalo de una razón de riesgos instantáneos incluye 1, una diferencia entre los grupos no está establecida estadísticamente.","synonyme":["IC","Rango de confianza"],"synonyme_en":["IC","Rango de confianza"],"siehe":["hazard-ratio","metaanalyse"],"seiten":["studien.html"]},{"slug":"konzentration","begriff":"Concentración","begriff_en":"Concentración","kategorie":"handhabung","kurz":"La concentración indica cuánto de una sustancia está disuelto en un volumen dado de líquido, generalmente en mg por ml.","kurz_en":"La concentración indica cuánto de una sustancia está disuelto en un volumen dado de líquido, generalmente en mg por ml.","quellen":[{"titel":"Libro de oro IUPAC: Concentración en masa","titel_en":"Libro de oro IUPAC: Concentración en masa","url":"https://goldbook.iupac.org/terms/view/M03713"}],"text":"La concentración en masa relaciona la masa de una sustancia especificada con el volumen final de la solución, por ejemplo en mg/ml. El peso del polvo y la masa real del péptido pueden diferir. Este valor describe la composición, no una aplicación.","text_en":"La concentración en masa relaciona la masa de una sustancia especificada con el volumen final de la solución, por ejemplo en mg/ml. El peso del polvo y la masa real del péptido pueden diferir. Este valor describe la composición, no una aplicación.","siehe":["rekonstitution","milligramm-mikrogramm","aliquot"]},{"slug":"kpv","begriff":"KPV","begriff_en":"KPV","kategorie":"wirkstoff","kurz":"Tripeptido derivado de melanocortina investigado en modelos de inflamación preclínicos","kurz_en":"Tripeptido derivado de melanocortina investigado en modelos de inflamación preclínicos","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 18092346","titel_en":"PubMed: Publicación de investigación, PMID 18092346","url":"https://pubmed.ncbi.nlm.nih.gov/18092346/"}],"text":"KPV significa lisina-prolina-valina, un fragmento corto en el contexto de la melanocortina. El artículo citado lo investiga en modelos murinos de enfermedad inflamatoria intestinal. Esto no es evidencia clínica de uso.","text_en":"KPV significa lisina-prolina-valina, un fragmento corto en el contexto de la melanocortina. El artículo citado lo investiga en modelos murinos de enfermedad inflamatoria intestinal. Esto no es evidencia clínica de uso.","synonyme":["Lys-Pro-Val","alpha-MSH(11-13)"],"synonyme_en":["Lys-Pro-Val","alpha-MSH(11-13)"],"link":"wirkstoffe/kpv.html"},{"slug":"kupferpeptid","begriff":"Péptidos de cobre","begriff_en":"Péptidos de cobre","kategorie":"klassen","kurz":"Los péptidos de cobre son complejos de un pequeño péptido e iones de cobre, el mejor conocido es GHK-Cu.","kurz_en":"Los péptidos de cobre son complejos de un pequeño péptido e iones de cobre, el mejor conocido es GHK-Cu.","quellen":[{"titel":"GHK como péptido de unión a cobre en cristalografía","titel_en":"GHK como péptido de unión a cobre en cristalografía","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7709198/"}],"text":"Los péptidos de cobre son compuestos en los que un pequeño péptido coordina un ion de cobre. El ejemplo mejor conocido es GHK, un péptido de tres aminoácidos encontrado en el plasma sanguíneo, saliva y orina humana, donde ocurre naturalmente unido al cobre. En su forma de complejo de cobre, GHK-Cu se estudia principalmente en investigación de la piel, con datos preclínicos adicionales sobre tejido conectivo y cicatrización de heridas.","text_en":"Los péptidos de cobre son compuestos en los que un pequeño péptido coordina un ion de cobre. El ejemplo mejor conocido es GHK, un péptido de tres aminoácidos encontrado en el plasma sanguíneo, saliva y orina humana, donde ocurre naturalmente unido al cobre. En su forma de complejo de cobre, GHK-Cu se estudia principalmente en investigación de la piel, con datos preclínicos adicionales sobre tejido conectivo y cicatrización de heridas.","synonyme":["Complejos GHK-Cu"],"synonyme_en":["Complejos GHK-Cu"],"siehe":["aminosaeure","peptid"],"wirkstoffe":["ghk-cu"],"seiten":["peptid-1x1.html"]},{"slug":"lagerung","begriff":"Almacenamiento","begriff_en":"Almacenamiento","kategorie":"handhabung","kurz":"El almacenamiento describe cómo se conserva un péptido antes de su uso, generalmente fresco, seco y oscuro dependiendo de su estado.","kurz_en":"El almacenamiento describe cómo se conserva un péptido antes de su uso, generalmente fresco, seco y oscuro dependiendo de su estado.","quellen":[{"titel":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","titel_en":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"La estabilidad depende de la secuencia, la formulación y las condiciones, entre otros factores. La especificación del material y los datos de estabilidad comprobados son decisivos.","text_en":"La estabilidad depende de la secuencia, la formulación y las condiciones, entre otros factores. La especificación del material y los datos de estabilidad comprobados son decisivos.","siehe":["lyophilisat","lichtschutz","rekonstitution"]},{"slug":"lichtschutz","begriff":"Protección contra la luz","begriff_en":"Protección contra la luz","kategorie":"handhabung","kurz":"La protección contra la luz cubre medidas que protegen una muestra de la exposición a la luz, como viales ámbar o almacenamiento en la oscuridad.","kurz_en":"La protección contra la luz cubre medidas que protegen una muestra de la exposición a la luz, como viales ámbar o almacenamiento en la oscuridad.","quellen":[{"titel":"ICH Q1B: Pruebas de fotestabilidad","titel_en":"ICH Q1B: Pruebas de fotestabilidad","url":"https://www.ema.europa.eu/en/scientific-guidelines/ich-q1b-photostability-testing-new-active-substances-medicinal-products"}],"text":"Las pruebas de fotestabilidad investigan si la luz cambia una sustancia o formulación. El embalaje adecuado puede limitar la exposición. Las condiciones requeridas son específicas del producto; la protección contra la luz por sí sola no establece una vida útil particular.","text_en":"Las pruebas de fotestabilidad investigan si la luz cambia una sustancia o formulación. El embalaje adecuado puede limitar la exposición. Las condiciones requeridas son específicas del producto; la protección contra la luz por sí sola no establece una vida útil particular.","siehe":["lagerung","lyophilisat"]},{"slug":"ll-37","begriff":"LL-37","begriff_en":"LL-37","kategorie":"wirkstoff","kurz":"Péptido antimicrobiano endógeno también investigado en investigación de heridas clínicas.","kurz_en":"Péptido antimicrobiano endógeno también investigado en investigación de heridas clínicas.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 25041740","titel_en":"PubMed: Publicación de investigación, PMID 25041740","url":"https://pubmed.ncbi.nlm.nih.gov/25041740/"}],"text":"El ensayo aleatorizado enlazado investiga LL-37 en úlceras venosas de pierna difíciles de curar. Sus hallazgos conciernen a la preparación y el diseño específicos del estudio, no a todos los productos etiquetados como LL-37.","text_en":"El ensayo aleatorizado enlazado investiga LL-37 en úlceras venosas de pierna difíciles de curar. Sus hallazgos conciernen a la preparación y el diseño específicos del estudio, no a todos los productos etiquetados como LL-37.","synonyme":["Catelicidina","hCAP18(134-170)","Catelicidina humana"],"synonyme_en":["Catelicidina","hCAP18(134-170)","Catelicidina humana"],"link":"wirkstoffe/ll-37.html"},{"slug":"lyophilisat","begriff":"Liofilizado","begriff_en":"Liofilizado","kategorie":"handhabung","kurz":"Material obtenido por liofilización, como un polvo en un vial de laboratorio.","kurz_en":"Material obtenido por liofilización, como un polvo en un vial de laboratorio.","quellen":[{"titel":"FDA: Liofilización","titel_en":"FDA: Liofilización","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"La liofilización elimina agua de una muestra congelada bajo vacío. Deja un polvo seco o una torta porosa. La estabilidad y vida útil dependen de la sustancia, la formulación y el embalaje; la forma física por sí sola no las garantiza.","text_en":"La liofilización elimina agua de una muestra congelada bajo vacío. Deja un polvo seco o una torta porosa. La estabilidad y vida útil dependen de la sustancia, la formulación y el embalaje; la forma física por sí sola no las garantiza.","siehe":["rekonstitution","lagerung","lichtschutz","charge"]},{"slug":"massenspektrometrie","begriff":"Espectrometría de masas","begriff_en":"Espectrometría de masas","kategorie":"labor","kurz":"La espectrometría de masas determina el peso molecular de una muestra y así confirma qué molécula está realmente presente.","kurz_en":"La espectrometría de masas determina el peso molecular de una muestra y así confirma qué molécula está realmente presente.","quellen":[{"titel":"FDA: Análisis de mezclas complejas y péptidos","titel_en":"FDA: Análisis de mezclas complejas y péptidos","url":"https://www.fda.gov/industry/generic-drug-user-fee-amendments/fys-2013-2017-regulatory-science-report-complex-mixtures-and-peptides"}],"text":"Combinada con cromatografía líquida (LC-MS), verifica la identidad de un péptido independientemente de su valor de pureza. Un valor de pureza alto sin esta verificación no dice nada sobre si la molécula correcta está presente en absoluto.","text_en":"Combinada con cromatografía líquida (LC-MS), verifica la identidad de un péptido independientemente de su valor de pureza. Un valor de pureza alto sin esta verificación no dice nada sobre si la molécula correcta está presente en absoluto.","synonyme":["MS"],"synonyme_en":["MS"],"siehe":["identitaet","hplc","coa"],"seiten":["peptid-1x1.html"]},{"slug":"melanocortin","begriff":"Melanocortinas","begriff_en":"Melanocortinas","kategorie":"klassen","kurz":"Las melanocortinas son hormonas peptídicas derivadas de POMC que se unen a cinco tipos de receptores que regulan la piel, el apetito y la respuesta sexual.","kurz_en":"Las melanocortinas son hormonas peptídicas derivadas de POMC que se unen a cinco tipos de receptores que regulan la piel, el apetito y la respuesta sexual.","quellen":[{"titel":"NCBI Endotext: Receptores de melanocortina","titel_en":"NCBI Endotext: Receptores de melanocortina","url":"https://www.ncbi.nlm.nih.gov/books/NBK279118/"}],"text":"Las melanocortinas son una familia de hormonas peptídicas derivadas de la proteína precursora proopiomelanocortina (POMC), incluyendo alfa-MSH y ACTH. Se unen a cinco receptores de melanocortina distintos (MC1R a MC5R) que regulan la pigmentación de la piel, el apetito, el balance energético, los procesos inflamatorios y la respuesta sexual, entre otras funciones. Los agonistas de receptores de melanocortina sintéticos se dirigen a receptores individuales dentro de este sistema.","text_en":"Las melanocortinas son una familia de hormonas peptídicas derivadas de la proteína precursora proopiomelanocortina (POMC), incluyendo alfa-MSH y ACTH. Se unen a cinco receptores de melanocortina distintos (MC1R a MC5R) que regulan la pigmentación de la piel, el apetito, el balance energético, los procesos inflamatorios y la respuesta sexual, entre otras funciones. Los agonistas de receptores de melanocortina sintéticos se dirigen a receptores individuales dentro de este sistema.","synonyme":["Sistema de melanocortina"],"synonyme_en":["Sistema de melanocortina"],"siehe":["rezeptor","agonist","peptidhormon"],"wirkstoffe":["melanotan-2","pt-141"],"seiten":["peptid-1x1.html"]},{"slug":"melanotan-2","begriff":"Melanotan II","begriff_en":"Melanotan II","kategorie":"wirkstoff","kurz":"Análogo de melanocortina sintético investigado en estudios clínicos tempranos.","kurz_en":"Análogo de melanocortina sintético investigado en estudios clínicos tempranos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 8637402","titel_en":"PubMed: Publicación de investigación, PMID 8637402","url":"https://pubmed.ncbi.nlm.nih.gov/8637402/"}],"text":"El artículo de fase I citado investiga melanotan II en un pequeño estudio piloto. No establece una evaluación fiable de beneficio-riesgo para uso general.","text_en":"El artículo de fase I citado investiga melanotan II en un pequeño estudio piloto. No establece una evaluación fiable de beneficio-riesgo para uso general.","synonyme":["MT-2","MT2"],"synonyme_en":["MT-2","MT2"],"link":"wirkstoffe/melanotan-2.html"},{"slug":"metaanalyse","begriff":"Metaanálisis","begriff_en":"Metaanálisis","kategorie":"studien","kurz":"Una síntesis estadística de múltiples estudios que abordan una pregunta compartida.","kurz_en":"Una síntesis estadística de múltiples estudios que abordan una pregunta compartida.","quellen":[{"titel":"NCI: meta análisis","titel_en":"NCI: meta análisis","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/meta-analysis"}],"text":"Un metaanálisis combina estadísticamente resultados comparables de múltiples estudios. Puede proporcionar estimaciones más precisas. Su fortaleza depende de la calidad, comparabilidad y exhaustividad de la evidencia incluida.","text_en":"Un metaanálisis combina estadísticamente resultados comparables de múltiples estudios. Puede proporcionar estimaciones más precisas. Su fortaleza depende de la calidad, comparabilidad y exhaustividad de la evidencia incluida.","siehe":["klinische-studie","peer-review"],"seiten":["studien.html"]},{"slug":"milligramm-mikrogramm","begriff":"Miligramo / Microgramo","begriff_en":"Miligramo / Microgramo","kategorie":"handhabung","kurz":"Un miligramo equivale a 1000 microgramos, la unidad de masa estándar para pequeñas cantidades de péptidos en etiquetas y CoAs.","kurz_en":"Un miligramo equivale a 1000 microgramos, la unidad de masa estándar para pequeñas cantidades de péptidos en etiquetas y CoAs.","quellen":[{"titel":"BIPM: prefijos SI","titel_en":"BIPM: prefijos SI","url":"https://www.bipm.org/en/committees/cg/cgpm/11-1960/resolution-12"}],"text":"Los miligramos (mg) y los microgramos (µg) son ambas subunidades del gramo y difieren por un factor de 1000. Las etiquetas de viales y los CoAs suelen indicar la cantidad de péptido en miligramos, mientras que las cifras de componentes individuales a veces aparecen en microgramos. La calculadora en esta página convierte entre gramos, miligramos y microgramos en una base puramente matemática.","text_en":"Los miligramos (mg) y los microgramos (µg) son ambas subunidades del gramo y difieren por un factor de 1000. Las etiquetas de viales y los CoAs suelen indicar la cantidad de péptido en miligramos, mientras que las cifras de componentes individuales a veces aparecen en microgramos. La calculadora en esta página convierte entre gramos, miligramos y microgramos en una base puramente matemática.","siehe":["konzentration","internationale-einheit"],"seiten":["rechner.html"]},{"slug":"mitochondriales-peptid","begriff":"Péptidos mitocondriales","begriff_en":"Péptidos mitocondriales","kategorie":"klassen","kurz":"Los péptidos mitocondriales se dirigen a la producción de energía celular o se originan del ADN mitocondrial.","kurz_en":"Los péptidos mitocondriales se dirigen a la producción de energía celular o se originan del ADN mitocondrial.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, investigación preclínica","titel_en":"Lee et al. (2015): MOTS-c, investigación preclínica","url":"https://doi.org/10.1016/j.cmet.2015.02.009"},{"titel":"Cho et al. (2007): Dianas mitocondriales en un modelo de rata","titel_en":"Cho et al. (2007): Dianas mitocondriales en un modelo de rata","url":"https://pubmed.ncbi.nlm.nih.gov/17429296/"}],"text":"Los péptidos mitocondriales no son una clase de sustancia única en el sentido clásico. El término agrupa péptidos que se unen a la membrana mitocondrial interna o están codificados por ADN mitocondrial en lugar de ADN nuclear. El segundo grupo incluye un péptido corto derivado del gen 12S rRNA mitocondrial, estudiado en investigación metabólica. Otro ejemplo se une a la cardiolipina en la membrana interna y se utiliza en investigaciones sobre el envejecimiento celular y el metabolismo energético.","text_en":"Los péptidos mitocondriales no son una clase de sustancia única en el sentido clásico. El término agrupa péptidos que se unen a la membrana mitocondrial interna o están codificados por ADN mitocondrial en lugar de ADN nuclear. El segundo grupo incluye un péptido corto derivado del gen 12S rRNA mitocondrial, estudiado en investigación metabólica. Otro ejemplo se une a la cardiolipina en la membrana interna y se utiliza en investigaciones sobre el envejecimiento celular y el metabolismo energético.","synonyme":["Péptidos mitocondriales"],"synonyme_en":["Péptidos mitocondriales"],"siehe":["praeklinisch","in-vitro"],"wirkstoffe":["mots-c","ss-31"],"seiten":["studien.html"]},{"slug":"mots-c","begriff":"MOTS-c","begriff_en":"MOTS-c","kategorie":"wirkstoff","kurz":"Péptido derivado del ADN mitocondrial investigado en modelos metabólicos preclínicos.","kurz_en":"Péptido derivado del ADN mitocondrial investigado en modelos metabólicos preclínicos.","quellen":[{"titel":"Lee et al. (2015): MOTS-c, investigación preclínica","titel_en":"Lee et al. (2015): MOTS-c, investigación preclínica","url":"https://doi.org/10.1016/j.cmet.2015.02.009"}],"text":"El artículo de descubrimiento describe una secuencia corta codificada en el ADN mitocondrial y la investiga en modelos celulares y animales. Su papel en la investigación mitocondrial no establece un beneficio de un producto comercializado.","text_en":"El artículo de descubrimiento describe una secuencia corta codificada en el ADN mitocondrial y la investiga en modelos celulares y animales. Su papel en la investigación mitocondrial no establece un beneficio de un producto comercializado.","synonyme":["Péptido Derivado Mitocondrial MOTS-c","Marco de Lectura Abierta Mitocondrial del rRNA 12S Tipo-c"],"synonyme_en":["Péptido Derivado Mitocondrial MOTS-c","Marco de Lectura Abierta Mitocondrial del rRNA 12S Tipo-c"],"link":"wirkstoffe/mots-c.html"},{"slug":"neuropeptid","begriff":"Neuropeptido","begriff_en":"Neuropeptido","kategorie":"grundlagen","kurz":"Un péptido que actúa como molécula de señalización entre células en el sistema nervioso.","kurz_en":"Un péptido que actúa como molécula de señalización entre células en el sistema nervioso.","quellen":[{"titel":"Purves et al.: neurotransmisores peptídicos","titel_en":"Purves et al.: neurotransmisores peptídicos","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Los neuropeptidos son péptidos liberados por células nerviosas que actúan como moléculas de señalización dentro del sistema nervioso. Diferen de los neurotransmisores clásicos por su estructura molecular más grande y también se unen a receptores específicos en células diana. En investigación, los neuropeptidos se utilizan entre otras cosas para mapear vías de señalización en el sistema nervioso central.","text_en":"Los neuropeptidos son péptidos liberados por células nerviosas que actúan como moléculas de señalización dentro del sistema nervioso. Diferen de los neurotransmisores clásicos por su estructura molecular más grande y también se unen a receptores específicos en células diana. En investigación, los neuropeptidos se utilizan entre otras cosas para mapear vías de señalización en el sistema nervioso central.","siehe":["peptid","peptidhormon","rezeptor"]},{"slug":"nootropikum","begriff":"Nootrópicos","begriff_en":"Nootrópicos","kategorie":"klassen","kurz":"Los nootrópicos son una clase de sustancias amplia estudiada en relación con la memoria, el aprendizaje o el procesamiento del estrés.","kurz_en":"Los nootrópicos son una clase de sustancias amplia estudiada en relación con la memoria, el aprendizaje o el procesamiento del estrés.","quellen":[{"titel":"Giurgea (1972): Origen del concepto de nootrópico","titel_en":"Giurgea (1972): Origen del concepto de nootrópico","url":"https://pubmed.ncbi.nlm.nih.gov/4541214/"}],"text":"acuñado por Giurgea en 1972, el término describe sustancias investigadas en relación con las funciones cognitivas. La etiqueta por sí sola no establece ni beneficio ni seguridad. Diferentes sustancias y diseños de estudio requieren una evaluación separada.","text_en":"acuñado por Giurgea en 1972, el término describe sustancias investigadas en relación con las funciones cognitivas. La etiqueta por sí sola no establece ni beneficio ni seguridad. Diferentes sustancias y diseños de estudio requieren una evaluación separada.","synonyme":["Fármacos inteligentes"],"synonyme_en":["Fármacos inteligentes"],"siehe":["neuropeptid","rezeptor"],"wirkstoffe":["semax","selank","dihexa"],"seiten":["peptid-1x1.html"]},{"slug":"oligopeptid","begriff":"Oligopéptido","begriff_en":"Oligopéptido","kategorie":"grundlagen","kurz":"Una cadena corta de aminoácidos, clasificada por longitud como di-, tri- o oligopéptido.","kurz_en":"Una cadena corta de aminoácidos, clasificada por longitud como di-, tri- o oligopéptido.","quellen":[{"titel":"Alberts et al.: Estructura de proteínas","titel_en":"Alberts et al.: Estructura de proteínas","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"langform":"Di-, tri- y oligopéptido","langform_en":"Di-, tri- y oligopéptido","text":"Los oligopéptidos contienen un pequeño número de aminoácidos. Dos forman un dipeptido y tres un tripeptido. El límite con polipéptidos más largos es una convención de nomenclatura, no un cambio distinto en el tipo molecular.","text_en":"Los oligopéptidos contienen un pequeño número de aminoácidos. Dos forman un dipeptido y tres un tripeptido. El límite con polipéptidos más largos es una convención de nomenclatura, no un cambio distinto en el tipo molecular.","synonyme":["Dipeptido","Tripeptido"],"synonyme_en":["Dipeptido","Tripeptido"],"siehe":["peptid","aminosaeure","protein"],"seiten":["peptid-1x1.html"]},{"slug":"oxytocin","begriff":"Oxitocina","begriff_en":"Oxitocina","kategorie":"wirkstoff","kurz":"Hormona peptídica endógena también investigada en estudios de comportamiento social.","kurz_en":"Hormona peptídica endógena también investigada en estudios de comportamiento social.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 15931222","titel_en":"PubMed: Publicación de investigación, PMID 15931222","url":"https://pubmed.ncbi.nlm.nih.gov/15931222/"}],"text":"El estudio de comportamiento enlazado investiga decisiones en un juego de confianza experimental. Tales hallazgos no establecen ni relaciones sociales generalmente mejoradas ni la seguridad de los productos comercializados libremente.","text_en":"El estudio de comportamiento enlazado investiga decisiones en un juego de confianza experimental. Tales hallazgos no establecen ni relaciones sociales generalmente mejoradas ni la seguridad de los productos comercializados libremente.","synonyme":["OXT","Pitocin"],"synonyme_en":["OXT","Pitocin"],"link":"wirkstoffe/oxytocin.html"},{"slug":"partnercode","begriff":"Código de socio","begriff_en":"Código de socio","kategorie":"vergleich","kurz":"Un código asociado a un programa de afiliados, sujeto a los términos del proveedor.","kurz_en":"Un código asociado a un programa de afiliados, sujeto a los términos del proveedor.","quellen":[{"titel":"Peptide Compass: Nuestra información de afiliación","titel_en":"Peptide Compass: Nuestra información de afiliación","url":"https://peptidkompass.com/es/affiliate-hinweis.html"}],"text":"Un código de socio está asociado a un programa de afiliados. Si genera un descuento o comisión depende de los términos aplicables. Las asociaciones y códigos documentados actualmente se enumeran en nuestra información de afiliación; no cambian la puntuación de documentación.","text_en":"Un código de socio está asociado a un programa de afiliados. Si genera un descuento o comisión depende de los términos aplicables. Las asociaciones y códigos documentados actualmente se enumeran en nuestra información de afiliación; no cambian la puntuación de documentación.","siehe":["affiliate-link"],"seiten":["affiliate-hinweis.html","deals.html"]},{"slug":"peer-review","begriff":"Revisión por pares","begriff_en":"Revisión por pares","kategorie":"studien","kurz":"Revisión por expertos de un manuscrito de estudio por especialistas independientes antes de la publicación.","kurz_en":"Revisión por expertos de un manuscrito de estudio por especialistas independientes antes de la publicación.","quellen":[{"titel":"NIH: Directrices para la revisión por pares científica","titel_en":"NIH: Directrices para la revisión por pares científica","url":"https://oir.nih.gov/system/files/media/file/2026-01/guidelines-conduct_research.pdf"}],"text":"En la revisión por pares, expertos independientes verifican la metodología, el análisis de datos y las conclusiones de un manuscrito antes de la publicación. Pueden solicitar correcciones o rechazar el trabajo. Una publicación revisada por pares se considera más confiable que un texto no revisado, aunque no es una garantía contra errores.","text_en":"En la revisión por pares, expertos independientes verifican la metodología, el análisis de datos y las conclusiones de un manuscrito antes de la publicación. Pueden solicitar correcciones o rechazar el trabajo. Una publicación revisada por pares se considera más confiable que un texto no revisado, aunque no es una garantía contra errores.","siehe":["preprint","pubmed"],"seiten":["studien.html"]},{"slug":"pentadeca-arginate","begriff":"Pentadeca Arginate (PDA)","begriff_en":"Pentadeca Arginate","kategorie":"wirkstoff","kurz":"Designación comercial para una forma comercializada como sal de arginina de BPC-157.","kurz_en":"Designación comercial para una forma comercializada como sal de arginina de BPC-157.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 27847966","titel_en":"PubMed: Publicación de investigación, PMID 27847966","url":"https://pubmed.ncbi.nlm.nih.gov/27847966/"}],"text":"El estudio original citado investiga BPC-157. No establece propiedades especiales de una forma de sal vendida como Pentadeca Arginate. No se ha establecido aquí una fuente confiable y dedicada que demuestre una solubilidad o estabilidad superior de esta forma comercializada.","text_en":"El estudio original citado investiga BPC-157. No establece propiedades especiales de una forma de sal vendida como Pentadeca Arginate. No se ha establecido aquí una fuente confiable y dedicada que demuestre una solubilidad o estabilidad superior de esta forma comercializada.","synonyme":["PDA","Sal de arginato de BPC-157"],"synonyme_en":["PDA","Sal de arginato de BPC-157"],"link":"wirkstoffe/pentadeca-arginate.html"},{"slug":"peptid","begriff":"Péptido","begriff_en":"Péptidos","kategorie":"grundlagen","kurz":"Una cadena corta de aminoácidos unidos por enlaces peptídicos.","kurz_en":"Una cadena corta de aminoácidos unidos por enlaces peptídicos.","quellen":[{"titel":"NCI: péptido","titel_en":"NCI: péptido","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/peptide"}],"text":"Dos aminoácidos unidos forman un dipeptido; tres forman un tripeptido. Las cadenas más largas también se denominan polipéptidos. Un límite fijo de 50 aminoácidos no distingue los péptidos de las proteínas en todos los campos.","text_en":"Dos aminoácidos unidos forman un dipeptido; tres forman un tripeptido. Las cadenas más largas también se denominan polipéptidos. Un límite fijo de 50 aminoácidos no distingue los péptidos de las proteínas en todos los campos.","synonyme":["Péptidos"],"synonyme_en":["Péptidos"],"siehe":["aminosaeure","peptidbindung","oligopeptid","protein"],"seiten":["peptid-1x1.html"]},{"slug":"peptidbindung","begriff":"Enlace peptídico","begriff_en":"Enlace peptídico","kategorie":"grundlagen","kurz":"El enlace químico que une dos aminoácidos en una cadena.","kurz_en":"El enlace químico que une dos aminoácidos en una cadena.","quellen":[{"titel":"Alberts et al.: Estructura de proteínas","titel_en":"Alberts et al.: Estructura de proteínas","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"Un enlace peptídico se forma cuando el grupo carboxilo de un aminoácido reacciona con el grupo amino del siguiente, liberando una molécula de agua en el proceso. Este enlace se repite a lo largo de toda la cadena y forma la columna vertebral de los péptidos y las proteínas. El orden de los aminoácidos unidos de esta manera establece la secuencia.","text_en":"Un enlace peptídico se forma cuando el grupo carboxilo de un aminoácido reacciona con el grupo amino del siguiente, liberando una molécula de agua en el proceso. Este enlace se repite a lo largo de toda la cadena y forma la columna vertebral de los péptidos y las proteínas. El orden de los aminoácidos unidos de esta manera establece la secuencia.","siehe":["aminosaeure","peptid","sequenz"]},{"slug":"peptidgehalt","begriff":"Contenido neto de péptido","begriff_en":"Contenido neto de péptido","kategorie":"labor","kurz":"El contenido neto de péptido indica qué parte de la masa de un polvo es el péptido en sí.","kurz_en":"El contenido neto de péptido indica qué parte de la masa de un polvo es el péptido en sí.","quellen":[{"titel":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","titel_en":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"El contenido de péptido es la fracción real del péptido de una muestra. El agua y otros constituyentes pueden hacer que la masa del polvo difiera de la masa del péptido.","text_en":"El contenido de péptido es la fracción real del péptido de una muestra. El agua y otros constituyentes pueden hacer que la masa del polvo difiera de la masa del péptido.","siehe":["reinheit","gegenion","coa"],"seiten":["methodik.html"]},{"slug":"peptidhormon","begriff":"Hormona peptídica","begriff_en":"Hormona peptídica","kategorie":"grundlagen","kurz":"Una hormona que el cuerpo produce que es químicamente una cadena de aminoácidos.","kurz_en":"Una hormona que el cuerpo produce que es químicamente una cadena de aminoácidos.","quellen":[{"titel":"Purves et al.: neurotransmisores peptídicos","titel_en":"Purves et al.: neurotransmisores peptídicos","url":"https://www.ncbi.nlm.nih.gov/books/NBK10873/"}],"text":"Una hormona peptídica es una molécula de señalización construida a partir de una cadena de aminoácidos, a diferencia de las hormonas esteroideas, que se basan en el colesterol. Las hormonas peptídicas son producidas en glándulas o células especializadas y se unen a receptores en células diana. La insulina es un ejemplo bien conocido de una hormona peptídica endógena.","text_en":"Una hormona peptídica es una molécula de señalización construida a partir de una cadena de aminoácidos, a diferencia de las hormonas esteroideas, que se basan en el colesterol. Las hormonas peptídicas son producidas en glándulas o células especializadas y se unen a receptores en células diana. La insulina es un ejemplo bien conocido de una hormona peptídica endógena.","siehe":["peptid","rezeptor","neuropeptid"]},{"slug":"placebo","begriff":"Placebo","begriff_en":"Placebo","kategorie":"studien","kurz":"Una preparación falsa sin ingrediente activo, utilizada para comparar contra una sustancia real en un ensayo. Separa los efectos reales de los esperados.","kurz_en":"Una preparación falsa sin ingrediente activo, utilizada para comparar contra una sustancia real en un ensayo. Separa los efectos reales de los esperados.","quellen":[{"titel":"NCI: placebo","titel_en":"NCI: placebo","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/placebo"}],"text":"Un placebo se parece a la preparación probada pero no contiene ingrediente activo. En un diseño de estudio sirve como grupo de comparación, mostrando cuánto de la respuesta proviene de la expectativa del participante en lugar de la sustancia misma. El control con placebo es una característica central de los ensayos clínicos informativos, a menudo combinado con el cegamiento.","text_en":"Un placebo se parece a la preparación probada pero no contiene ingrediente activo. En un diseño de estudio sirve como grupo de comparación, mostrando cuánto de la respuesta proviene de la expectativa del participante en lugar de la sustancia misma. El control con placebo es una característica central de los ensayos clínicos informativos, a menudo combinado con el cegamiento.","synonyme":["Preparación inactiva"],"synonyme_en":["Preparación inactiva"],"siehe":["rct","Ciego doble"],"seiten":["studien.html"]},{"slug":"praeklinisch","begriff":"Preclínico","begriff_en":"Preclínico","kategorie":"studien","kurz":"La etapa de investigación antes de cualquier uso humano: cultivo celular y modelo animal. Los ensayos clínicos siguen solo después de esta etapa.","kurz_en":"La etapa de investigación antes de cualquier uso humano: cultivo celular y modelo animal. Los ensayos clínicos siguen solo después de esta etapa.","quellen":[{"titel":"NCI: estudio preclínico","titel_en":"NCI: estudio preclínico","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/preclinical-study"}],"text":"La investigación preclínica cubre experimentos in vitro e in vivo que comprueban los efectos y la seguridad iniciales antes de que una sustancia sea probada en humanos. Proporciona la base de datos para un posible ensayo clínico posterior. Un resultado preclínico por sí solo no respalda una afirmación sobre humanos.","text_en":"La investigación preclínica cubre experimentos in vitro e in vivo que comprueban los efectos y la seguridad iniciales antes de que una sustancia sea probada en humanos. Proporciona la base de datos para un posible ensayo clínico posterior. Un resultado preclínico por sí solo no respalda una afirmación sobre humanos.","synonyme":["Investigación preclínica"],"synonyme_en":["Investigación preclínica"],"siehe":["in-vitro","in-vivo","tiermodell","klinische-studie"],"seiten":["studien.html"]},{"slug":"preis-pro-mg","begriff":"Precio por miligramo","begriff_en":"Precio por miligramo","kategorie":"vergleich","kurz":"El precio por miligramo hace que las ofertas con diferentes tamaños de paquete sean directamente comparables.","kurz_en":"El precio por miligramo hace que las ofertas con diferentes tamaños de paquete sean directamente comparables.","quellen":[{"titel":"Peptide Compass: Nuestra metodología de comparación","titel_en":"Peptide Compass: Nuestra metodología de comparación","url":"https://peptidkompass.com/es/methodik.html"}],"text":"La cifra es el precio de lista dividido por el contenido en miligramos de un producto, comparado para la misma sustancia activa y moneda. Los términos de envío, disponibilidad y descuento solo se incluyen cuando están documentados explícitamente. Una cifra más baja no dice nada sobre la pureza o la documentación.","text_en":"La cifra es el precio de lista dividido por el contenido en miligramos de un producto, comparado para la misma sustancia activa y moneda. Los términos de envío, disponibilidad y descuento solo se incluyen cuando están documentados explícitamente. Una cifra más baja no dice nada sobre la pureza o la documentación.","siehe":["dokumentationsscore"],"seiten":["vergleich.html","rechner.html"]},{"slug":"preprint","begriff":"Preprint","begriff_en":"Preprint","kategorie":"studien","kurz":"Un manuscrito de estudio publicado antes de la revisión por pares. Los resultados se consideran preliminares, no aún verificados de forma independiente.","kurz_en":"Un manuscrito de estudio publicado antes de la revisión por pares. Los resultados se consideran preliminares, no aún verificados de forma independiente.","quellen":[{"titel":"NLM: Limitaciones de PubMed y preprints","titel_en":"NLM: Limitaciones de PubMed y preprints","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"Un preprint se publica en una plataforma abierta antes de que una revista lo haya revisado. Esto acelera el intercambio de resultados pero significa que la metodología y las conclusiones aún no han sido verificadas de forma independiente. El contenido de un preprint debe ser juzgado con mayor cautela que una publicación revisada por pares.","text_en":"Un preprint se publica en una plataforma abierta antes de que una revista lo haya revisado. Esto acelera el intercambio de resultados pero significa que la metodología y las conclusiones aún no han sido verificadas de forma independiente. El contenido de un preprint debe ser juzgado con mayor cautela que una publicación revisada por pares.","siehe":["peer-review","pubmed"],"seiten":["studien.html"]},{"slug":"protein","begriff":"Proteína","begriff_en":"Proteína","kategorie":"grundlagen","kurz":"Una molécula hecha de cadenas de aminoácidos con diversos roles biológicos.","kurz_en":"Una molécula hecha de cadenas de aminoácidos con diversos roles biológicos.","quellen":[{"titel":"NCI: proteína","titel_en":"NCI: proteína","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/protein"}],"text":"Las proteínas consisten en una o más cadenas de aminoácidos. Su secuencia y estructura espacial determinan sus propiedades. Una longitud de cadena fija por sí sola no define la distinción de los péptidos.","text_en":"Las proteínas consisten en una o más cadenas de aminoácidos. Su secuencia y estructura espacial determinan sus propiedades. Una longitud de cadena fija por sí sola no define la distinción de los péptidos.","synonyme":["Proteína"],"synonyme_en":["Proteína"],"siehe":["peptid","aminosaeure","oligopeptid"],"seiten":["peptid-1x1.html"]},{"slug":"proteolyse","begriff":"Proteólisis","begriff_en":"Proteólisis","kategorie":"grundlagen","kurz":"La descomposición enzimática de una cadena de aminoácidos en fragmentos más pequeños.","kurz_en":"La descomposición enzimática de una cadena de aminoácidos en fragmentos más pequeños.","quellen":[{"titel":"Alberts et al.: Síntesis y degradación de proteínas","titel_en":"Alberts et al.: Síntesis y degradación de proteínas","url":"https://www.ncbi.nlm.nih.gov/books/NBK26829/"}],"text":"La proteólisis es el proceso por el cual enzimas llamadas proteasas escinden los enlaces peptídicos en una cadena de aminoácidos, rompiéndola en fragmentos más pequeños. Esta descomposición ocurre continuamente en el cuerpo y afecta cuánto tiempo permanece intacto un péptido, en otras palabras su vida media. Los estudios a menudo informan sobre la estabilidad proteolítica como medida de la durabilidad de un péptido.","text_en":"La proteólisis es el proceso por el cual enzimas llamadas proteasas escinden los enlaces peptídicos en una cadena de aminoácidos, rompiéndola en fragmentos más pequeños. Esta descomposición ocurre continuamente en el cuerpo y afecta cuánto tiempo permanece intacto un péptido, en otras palabras su vida media. Los estudios a menudo informan sobre la estabilidad proteolítica como medida de la durabilidad de un péptido.","siehe":["halbwertszeit","peptidbindung","bioverfuegbarkeit"]},{"slug":"pt-141","begriff":"PT-141 (bremelanotida)","begriff_en":"PT-141 (bremelanotida)","kategorie":"wirkstoff","kurz":"Bremelanotida, un agonista del receptor de melanocortina sintético investigado en ensayos clínicos.","kurz_en":"Bremelanotida, un agonista del receptor de melanocortina sintético investigado en ensayos clínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 31599840","titel_en":"PubMed: Publicación de investigación, PMID 31599840","url":"https://pubmed.ncbi.nlm.nih.gov/31599840/"}],"text":"PT-141 es otro nombre para bremelanotida. La publicación vinculada describe dos ensayos aleatorizados de fase III en una población de pacientes definida. Un producto de investigación vendido por una tienda no es equivalente a la preparación del estudio.","text_en":"PT-141 es otro nombre para bremelanotida. La publicación vinculada describe dos ensayos aleatorizados de fase III en una población de pacientes definida. Un producto de investigación vendido por una tienda no es equivalente a la preparación del estudio.","synonyme":["Bremelanotida","Vyleesi"],"synonyme_en":["Bremelanotida","Vyleesi"],"link":"wirkstoffe/pt-141.html"},{"slug":"pubmed","begriff":"PubMed","begriff_en":"PubMed","kategorie":"studien","kurz":"Una base de datos gratuita operada por la Biblioteca Nacional de Medicina de EE. UU. para literatura biomédica.","kurz_en":"Una base de datos gratuita operada por la Biblioteca Nacional de Medicina de EE. UU. para literatura biomédica.","quellen":[{"titel":"NLM: Limitaciones de PubMed y preprints","titel_en":"NLM: Limitaciones de PubMed y preprints","url":"https://pubmed.ncbi.nlm.nih.gov/disclaimer/"}],"text":"PubMed indexa millones de artículos de medicina y ciencias de la vida y generalmente muestra un resumen gratuito directamente. El texto completo a menudo se encuentra detrás del muro de pago de la revista respectiva. Una lista de PubMed confirma que un artículo está indexado, pero no dice nada sobre la calidad de ese estudio individual.","text_en":"PubMed indexa millones de artículos de medicina y ciencias de la vida y generalmente muestra un resumen gratuito directamente. El texto completo a menudo se encuentra detrás del muro de pago de la revista respectiva. Una lista de PubMed confirma que un artículo está indexado, pero no dice nada sobre la calidad de ese estudio individual.","siehe":["peer-review","preprint"],"seiten":["studien.html"]},{"slug":"rct","begriff":"RCT","begriff_en":"RCT","kategorie":"studien","kurz":"Un diseño de estudio con asignación aleatoria a un tratamiento y un grupo de control. Considerado el estándar de oro para demostrar un efecto.","kurz_en":"Un diseño de estudio con asignación aleatoria a un tratamiento y un grupo de control. Considerado el estándar de oro para demostrar un efecto.","quellen":[{"titel":"NCI: Ensayos clínicos aleatorizados","titel_en":"NCI: Ensayos clínicos aleatorizados","url":"https://www.cancer.gov/publications/patient-education/crs.pdf"}],"langform":"Ensayo controlado aleatorizado","langform_en":"Ensayo controlado aleatorizado","text":"En un ensayo controlado aleatorizado, los participantes se asignan al azar a un tratamiento o a un grupo de control, a menudo cegados también. Esto reduce el sesgo por expectativa o selección. Los ECA se consideran el estándar de oro metodológico en la investigación clínica, especialmente combinado con control de placebo.","text_en":"En un ensayo controlado aleatorizado, los participantes se asignan al azar a un tratamiento o a un grupo de control, a menudo cegados también. Esto reduce el sesgo por expectativa o selección. Los ECA se consideran el estándar de oro metodológico en la investigación clínica, especialmente combinado con control de placebo.","siehe":["placebo","Ciego doble","klinische-studie"],"seiten":["studien.html"]},{"slug":"reinheit","begriff":"Pureza","begriff_en":"Pureza","kategorie":"labor","kurz":"La pureza indica cuánto del área del pico del cromatograma de una muestra pertenece a la molécula principal, generalmente como porcentaje desde HPLC.","kurz_en":"La pureza indica cuánto del área del pico del cromatograma de una muestra pertenece a la molécula principal, generalmente como porcentaje desde HPLC.","quellen":[{"titel":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","titel_en":"Hoofnagle et al. (2016): Análisis de péptidos y manipulación de laboratorio","url":"https://pubmed.ncbi.nlm.nih.gov/26719571/"}],"text":"La pureza describe la proporción de la sustancia diana dentro de un método declarado. Un porcentaje de área de HPLC no establece completamente la composición.","text_en":"La pureza describe la proporción de la sustancia diana dentro de un método declarado. Un porcentaje de área de HPLC no establece completamente la composición.","siehe":["hplc","identitaet","peptidgehalt"],"seiten":["peptid-1x1.html"]},{"slug":"rekonstitution","begriff":"Reconstitución","begriff_en":"Reconstitución","kategorie":"handhabung","kurz":"La reconstitución es disolver un péptido liofilizado en un líquido para preparar una solución para uso de laboratorio.","kurz_en":"La reconstitución es disolver un péptido liofilizado en un líquido para preparar una solución para uso de laboratorio.","quellen":[{"titel":"FDA: Liofilización","titel_en":"FDA: Liofilización","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/lyophilization-parenteral-793"}],"text":"El término significa restaurar una forma líquida a partir de una preparación seca. El líquido adecuado depende de la sustancia y del procedimiento analítico. El término no implica un método general de preparación o administración.","text_en":"El término significa restaurar una forma líquida a partir de una preparación seca. El líquido adecuado depende de la sustancia y del procedimiento analítico. El término no implica un método general de preparación o administración.","siehe":["lyophilisat","bakteriostatisches-wasser","steriles-wasser","konzentration"],"seiten":["rechner.html"]},{"slug":"retatrutid","begriff":"Retatrutida","begriff_en":"Retatrutida","kategorie":"wirkstoff","kurz":"Agonista de triple receptor de péptido investigado en ensayos clínicos.","kurz_en":"Agonista de triple receptor de péptido investigado en ensayos clínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 37366315","titel_en":"PubMed: Publicación de investigación, PMID 37366315","url":"https://pubmed.ncbi.nlm.nih.gov/37366315/"}],"text":"El ensayo de fase II enlazado investiga un agonista en los receptores de GIP, GLP-1 y glucagón. Los resultados de ese ensayo no establecen la equivalencia de un producto comercializado bajo el mismo nombre.","text_en":"El ensayo de fase II enlazado investiga un agonista en los receptores de GIP, GLP-1 y glucagón. Los resultados de ese ensayo no establecen la equivalencia de un producto comercializado bajo el mismo nombre.","synonyme":["LY3437943"],"synonyme_en":["LY3437943"],"link":"wirkstoffe/retatrutid.html"},{"slug":"rezeptor","begriff":"Receptor","begriff_en":"Receptor","kategorie":"grundlagen","kurz":"Una proteína en o dentro de una célula a la que un péptido se une específicamente.","kurz_en":"Una proteína en o dentro de una célula a la que un péptido se une específicamente.","quellen":[{"titel":"NCI: receptor","titel_en":"NCI: receptor","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/receptor"}],"text":"Un receptor es una proteína que reconoce y se une específicamente a una molécula coincidente, como un péptido, similar a una cerradura y una llave. Esta unión desencadena una cadena de señalización dentro de la célula. En investigación, cuán fuertemente se une un péptido a un receptor dado se denomina afinidad y a menudo se estudia en el laboratorio utilizando cultivos celulares.","text_en":"Un receptor es una proteína que reconoce y se une específicamente a una molécula coincidente, como un péptido, similar a una cerradura y una llave. Esta unión desencadena una cadena de señalización dentro de la célula. En investigación, cuán fuertemente se une un péptido a un receptor dado se denomina afinidad y a menudo se estudia en el laboratorio utilizando cultivos celulares.","siehe":["agonist","peptidhormon","neuropeptid"]},{"slug":"rezeptpflicht","begriff":"Requisito de prescripción","begriff_en":"Requisito de prescripción","kategorie":"recht","kurz":"Un requisito de prescripción significa que un producto medicinal solo puede dispensarse contra una prescripción médica.","kurz_en":"Un requisito de prescripción significa que un producto medicinal solo puede dispensarse contra una prescripción médica.","quellen":[{"titel":"Ley de Medicamentos alemana, sección 48: Requisitos de prescripción","titel_en":"Ley de Medicamentos alemana, sección 48: Requisitos de prescripción","url":"https://www.gesetze-im-internet.de/amg_1976/__48.html"}],"text":"En Alemania, la sección 48 de la Ley de Medicamentos y el reglamento de medicamentos de prescripción son particularmente relevantes. Los requisitos de prescripción, el estado de producto medicinal y la autorización son preguntas separadas. La venta como producto químico de investigación no establece una exención general.","text_en":"En Alemania, la sección 48 de la Ley de Medicamentos y el reglamento de medicamentos de prescripción son particularmente relevantes. Los requisitos de prescripción, el estado de producto medicinal y la autorización son preguntas separadas. La venta como producto químico de investigación no establece una exención general.","siehe":["arzneimittel","zulassung"],"seiten":["peptid-1x1.html"]},{"slug":"ruo","begriff":"RUO","begriff_en":"RUO","kategorie":"recht","kurz":"Uso solo para investigación describe un propósito de investigación. La abreviatura por sí sola no establece el estado legal de un producto.","kurz_en":"Uso solo para investigación describe un propósito de investigación. La abreviatura por sí sola no establece el estado legal de un producto.","quellen":[{"titel":"Ley de Medicamentos alemana, sección 2: Definición de medicamentos","titel_en":"Ley de Medicamentos alemana, sección 2: Definición de medicamentos","url":"https://www.gesetze-im-internet.de/amg_1976/__2.html"},{"titel":"FDA (24 de agosto de 2026): Etiquetado RUO y uso previsto, USA","titel_en":"FDA (24 de agosto de 2026): Etiquetado RUO y uso previsto, USA","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/warning-letters/txp-innovations-llc-dba-tex-peptides-735067-08242026"}],"langform":"Uso solo para investigación","langform_en":"Uso solo para investigación","text":"La etiqueta describe el propósito previsto declarado por el proveedor. No es ni una autorización ni evidencia de pureza o seguridad. Si un producto califica legalmente como medicamento depende de criterios estatutarios y su presentación real, no solo de esta abreviatura.","text_en":"La etiqueta describe el propósito previsto declarado por el proveedor. No es ni una autorización ni evidencia de pureza o seguridad. Si un producto califica legalmente como medicamento depende de criterios estatutarios y su presentación real, no solo de esta abreviatura.","siehe":["arzneimittel","zulassung"],"seiten":["methodik.html"]},{"slug":"selank","begriff":"Selank","begriff_en":"Selank","kategorie":"wirkstoff","kurz":"Péptido sintético investigado en estudios de trastornos de ansiedad.","kurz_en":"Péptido sintético investigado en estudios de trastornos de ansiedad.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 18454096","titel_en":"PubMed: Publicación de investigación, PMID 18454096","url":"https://pubmed.ncbi.nlm.nih.gov/18454096/"}],"text":"El artículo clínico enlazado compara selank con medazepam en trastornos de ansiedad y neurastenia. Una publicación única no reemplaza ni una evaluación de evidencia exhaustiva ni la verificación de calidad de productos comercializados.","text_en":"El artículo clínico enlazado compara selank con medazepam en trastornos de ansiedad y neurastenia. Una publicación única no reemplaza ni una evaluación de evidencia exhaustiva ni la verificación de calidad de productos comercializados.","link":"wirkstoffe/selank.html"},{"slug":"semaglutid","begriff":"Semaglutida","begriff_en":"Semaglutida","kategorie":"wirkstoff","kurz":"Análogo GLP-1 con investigación clínica y productos medicinales autorizados.","kurz_en":"Análogo GLP-1 con investigación clínica y productos medicinales autorizados.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 33567185","titel_en":"PubMed: Publicación de investigación, PMID 33567185","url":"https://pubmed.ncbi.nlm.nih.gov/33567185/"},{"titel":"EMA: Autorización específica del producto Ozempic","titel_en":"EMA: Autorización específica del producto Ozempic","url":"https://www.ema.europa.eu/en/medicines/human/EPAR/ozempic"}],"text":"El artículo clínico enlazado investiga semaglutida en adultos con sobrepeso u obesidad. La evaluación de la EMA se refiere al producto medicinal específico Ozempic. Ni el ensayo ni la autorización verifican un producto de tienda de investigación con un nombre similar.","text_en":"El artículo clínico enlazado investiga semaglutida en adultos con sobrepeso u obesidad. La evaluación de la EMA se refiere al producto medicinal específico Ozempic. Ni el ensayo ni la autorización verifican un producto de tienda de investigación con un nombre similar.","link":"wirkstoffe/semaglutid.html"},{"slug":"semax","begriff":"Semax","begriff_en":"Semax","kategorie":"wirkstoff","kurz":"Heptapéptido sintético investigado en modelos de rata, entre otros estudios de investigación.","kurz_en":"Heptapéptido sintético investigado en modelos de rata, entre otros estudios de investigación.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 14556513","titel_en":"PubMed: Publicación de investigación, PMID 14556513","url":"https://pubmed.ncbi.nlm.nih.gov/14556513/"}],"text":"La publicación citada investiga el BDNF en diferentes regiones cerebrales de ratas. Estos son datos preclínicos. No establecen una mejora cognitiva en humanos.","text_en":"La publicación citada investiga el BDNF en diferentes regiones cerebrales de ratas. Estos son datos preclínicos. No establecen una mejora cognitiva en humanos.","link":"wirkstoffe/semax.html"},{"slug":"sequenz","begriff":"Secuencia","begriff_en":"Secuencia","kategorie":"grundlagen","kurz":"El orden fijo de los aminoácidos en una cadena de péptido o proteína.","kurz_en":"El orden fijo de los aminoácidos en una cadena de péptido o proteína.","quellen":[{"titel":"Alberts et al.: Estructura de proteínas","titel_en":"Alberts et al.: Estructura de proteínas","url":"https://www.ncbi.nlm.nih.gov/books/NBK26830/"}],"text":"La secuencia describe el orden en que los aminoácidos individuales se unen mediante enlaces peptídicos. Por lo general se escribe utilizando códigos estandarizados de una o tres letras por aminoácido. Dos péptidos hechos de los mismos aminoácidos pero en un orden diferente cuentan como moléculas diferentes, lo que hace que la secuencia sea un marcador de identidad clave.","text_en":"La secuencia describe el orden en que los aminoácidos individuales se unen mediante enlaces peptídicos. Por lo general se escribe utilizando códigos estandarizados de una o tres letras por aminoácido. Dos péptidos hechos de los mismos aminoácidos pero en un orden diferente cuentan como moléculas diferentes, lo que hace que la secuencia sea un marcador de identidad clave.","synonyme":["Secuencia de aminoácidos"],"synonyme_en":["Secuencia de aminoácidos"],"siehe":["aminosaeure","peptidbindung","identitaet"]},{"slug":"sermorelin","begriff":"Sermorelina","begriff_en":"Sermorelina","kategorie":"wirkstoff","kurz":"Péptido derivado de GHRH investigado en investigación endocrina.","kurz_en":"Péptido derivado de GHRH investigado en investigación endocrina.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 18031173","titel_en":"PubMed: Publicación de investigación, PMID 18031173","url":"https://pubmed.ncbi.nlm.nih.gov/18031173/"}],"text":"La revisión enlazada sitúa sermorelina en la investigación histórica sobre la deficiencia de hormona del crecimiento infantil. La literatura médica histórica no establece ni el estado de autorización actual ni la calidad de un producto comercial.","text_en":"La revisión enlazada sitúa sermorelina en la investigación histórica sobre la deficiencia de hormona del crecimiento infantil. La literatura médica histórica no establece ni el estado de autorización actual ni la calidad de un producto comercial.","synonyme":["GRF 1-29","GHRH(1-29)","Geref (nombre comercial histórico)"],"synonyme_en":["GRF 1-29","GHRH(1-29)","Geref (nombre comercial histórico)"],"link":"wirkstoffe/sermorelin.html"},{"slug":"ss-31","begriff":"SS-31 (elamipretida)","begriff_en":"SS-31 (elamipretida)","kategorie":"wirkstoff","kurz":"Elamipretida, un péptido sintético investigado en estudios de trastornos mitocondriales.","kurz_en":"Elamipretida, un péptido sintético investigado en estudios de trastornos mitocondriales.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 37268435","titel_en":"PubMed: Publicación de investigación, PMID 37268435","url":"https://pubmed.ncbi.nlm.nih.gov/37268435/"},{"titel":"FDA: Forzinity, aprobado el 19 de septiembre de 2025","titel_en":"FDA: Forzinity, aprobado el 19 de septiembre de 2025","url":"https://www.fda.gov/drugs/drug-trials-snapshots/drug-trials-snapshots-forzinity"}],"text":"El 19 de septiembre de 2025, la FDA otorgó aprobación acelerada a Forzinity, que contiene elamipretida, para un grupo de pacientes definido con síndrome de Barth. Esta aprobación de producto de EE. UU. no se aplica a los productos químicos de investigación vendidos como SS-31.","text_en":"El 19 de septiembre de 2025, la FDA otorgó aprobación acelerada a Forzinity, que contiene elamipretida, para un grupo de pacientes definido con síndrome de Barth. Esta aprobación de producto de EE. UU. no se aplica a los productos químicos de investigación vendidos como SS-31.","synonyme":["Elamipretida","MTP-131","Bendavia"],"synonyme_en":["Elamipretida","MTP-131","Bendavia"],"link":"wirkstoffe/ss-31.html"},{"slug":"steriles-wasser","begriff":"Agua estéril","begriff_en":"Agua estéril","kategorie":"handhabung","kurz":"Agua para la cual la esterilidad es una característica de producto especificada.","kurz_en":"Agua para la cual la esterilidad es una característica de producto especificada.","quellen":[{"titel":"FDA: Esterilidad y endotoxinas","titel_en":"FDA: Esterilidad y endotoxinas","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-technical-guides/bacterial-endotoxinspyrogens"}],"text":"La esterilidad y la ausencia de endotoxinas son propiedades diferentes. Los productos deben evaluarse con respecto a sus especificaciones; la palabra “estéril” no implica ni idoneidad universal como solvente ni una vida útil particular después de la apertura.","text_en":"La esterilidad y la ausencia de endotoxinas son propiedades diferentes. Los productos deben evaluarse con respecto a sus especificaciones; la palabra “estéril” no implica ni idoneidad universal como solvente ni una vida útil particular después de la apertura.","siehe":["bakteriostatisches-wasser","rekonstitution","sterilitaet"]},{"slug":"sterilitaet","begriff":"Esterilidad","begriff_en":"Esterilidad","kategorie":"labor","kurz":"La esterilidad describe la ausencia de microorganismos viables en una muestra, verificada mediante su propio ensayo de laboratorio dedicado.","kurz_en":"La esterilidad describe la ausencia de microorganismos viables en una muestra, verificada mediante su propio ensayo de laboratorio dedicado.","quellen":[{"titel":"FDA: Pruebas de esterilidad y controles de proceso","titel_en":"FDA: Pruebas de esterilidad y controles de proceso","url":"https://www.fda.gov/drugs/guidances-drugs/questions-and-answers-current-good-manufacturing-practice-regulations-production-and-process"}],"text":"La prueba es independiente de la pureza, identidad y valor de endotoxina, y se documenta por separado. Es importante principalmente para péptidos liofilizados que se disuelven y manipulan posteriormente en un entorno de laboratorio.","text_en":"La prueba es independiente de la pureza, identidad y valor de endotoxina, y se documenta por separado. Es importante principalmente para péptidos liofilizados que se disuelven y manipulan posteriormente en un entorno de laboratorio.","siehe":["endotoxin","coa"]},{"slug":"confounder","begriff":"Factor de confusión (confounder)","begriff_en":"Factor de confusión (confounder)","kategorie":"studien","kurz":"Factor vinculado tanto al resultado como a la característica estudiada que puede distorsionar o simular una asociación.","kurz_en":"Factor vinculado tanto al resultado como a la característica estudiada que puede distorsionar o simular una asociación.","quellen":[{"titel":"NLM MeSH: Confounding Factors, Epidemiologic","titel_en":"NLM MeSH: Confounding Factors, Epidemiologic","url":"https://www.ncbi.nlm.nih.gov/mesh/68015986"}],"text":"Un factor de confusión puede causar o prevenir el resultado de interés sin ser un paso intermedio de la característica estudiada. También está vinculado a esa característica y puede distorsionar una asociación o crear una. Ejemplo: quienes beben café fuman más a menudo en promedio, por lo que una afección pulmonar podría atribuirse erróneamente al café. Los estudios tienen en cuenta los factores de confusión mediante la asignación aleatoria o el ajuste estadístico.","text_en":"Un factor de confusión puede causar o prevenir el resultado de interés sin ser un paso intermedio de la característica estudiada. También está vinculado a esa característica y puede distorsionar una asociación o crear una. Ejemplo: quienes beben café fuman más a menudo en promedio, por lo que una afección pulmonar podría atribuirse erróneamente al café. Los estudios tienen en cuenta los factores de confusión mediante la asignación aleatoria o el ajuste estadístico.","synonyme":["Factor de confusión","Variable de confusión"],"synonyme_en":["Factor de confusión","Variable de confusión"],"siehe":["association","observational-study","rct"],"seiten":["studien.html"]},{"slug":"studienphasen","begriff":"Fases de ensayo","begriff_en":"Fases de ensayo","kategorie":"studien","kurz":"Las cuatro etapas de prueba clínica: fases I a III antes de la aprobación, fase IV después en el uso diario.","kurz_en":"Las cuatro etapas de prueba clínica: fases I a III antes de la aprobación, fase IV después en el uso diario.","quellen":[{"titel":"FDA: Fases de investigación clínica","titel_en":"FDA: Fases de investigación clínica","url":"https://www.fda.gov/patients/drug-development-process/step-3-clinical-research"}],"text":"El desarrollo clínico se describe a menudo en cuatro fases: Fase I investiga principalmente la seguridad y la tolerabilidad en voluntarios sanos o pacientes. La Fase II examina la evidencia inicial de eficacia y preguntas de seguridad adicionales. La Fase III investiga esto en grupos más grandes. La Fase IV cubre estudios después de la aprobación. La fase por sí sola no establece la calidad de un estudio individual.","text_en":"El desarrollo clínico se describe a menudo en cuatro fases: Fase I investiga principalmente la seguridad y la tolerabilidad en voluntarios sanos o pacientes. La Fase II examina la evidencia inicial de eficacia y preguntas de seguridad adicionales. La Fase III investiga esto en grupos más grandes. La Fase IV cubre estudios después de la aprobación. La fase por sí sola no establece la calidad de un estudio individual.","synonyme":["Fases I a IV"],"synonyme_en":["Fases I a IV"],"siehe":["klinische-studie","rct"],"seiten":["studien.html"]},{"slug":"survodutid","begriff":"Survodutida","begriff_en":"Survodutida","kategorie":"wirkstoff","kurz":"Agonista dual de glucagón y receptor GLP-1 investigado en ensayos clínicos.","kurz_en":"Agonista dual de glucagón y receptor GLP-1 investigado en ensayos clínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 38330987","titel_en":"PubMed: Publicación de investigación, PMID 38330987","url":"https://pubmed.ncbi.nlm.nih.gov/38330987/"}],"text":"El ensayo de fase II enlazado investiga survodutida como un agonista de receptor dual. Los datos del ensayo conciernen a la formulación y población probadas y no verifican la calidad de los productos químicos de investigación.","text_en":"El ensayo de fase II enlazado investiga survodutida como un agonista de receptor dual. Los datos del ensayo conciernen a la formulación y población probadas y no verifican la calidad de los productos químicos de investigación.","synonyme":["BI 456906"],"synonyme_en":["BI 456906"],"link":"wirkstoffe/survodutid.html"},{"slug":"tb-500","begriff":"TB-500","begriff_en":"TB-500","kategorie":"wirkstoff","kurz":"Un nombre utilizado en un artículo analítico original para un fragmento acetilado de timosin beta-4.","kurz_en":"Un nombre utilizado en un artículo analítico original para un fragmento acetilado de timosin beta-4.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 23084823","titel_en":"PubMed: Publicación de investigación, PMID 23084823","url":"https://pubmed.ncbi.nlm.nih.gov/23084823/"}],"text":"El artículo analítico enlazado identifica un fragmento acetilado en un producto etiquetado TB-500. Los hallazgos para la timosin beta-4 de longitud completa no se aplican automáticamente a este fragmento u otros productos comercializados.","text_en":"El artículo analítico enlazado identifica un fragmento acetilado en un producto etiquetado TB-500. Los hallazgos para la timosin beta-4 de longitud completa no se aplican automáticamente a este fragmento u otros productos comercializados.","synonyme":["Fragmento de timosina beta-4","Frag TB4"],"synonyme_en":["Fragmento de timosina beta-4","Frag TB4"],"link":"wirkstoffe/tb-500.html"},{"slug":"tesamorelin","begriff":"Tesamorelina","begriff_en":"Tesamorelina","kategorie":"wirkstoff","kurz":"Análogo de factor liberador de hormona del crecimiento sintético investigado en ensayos clínicos.","kurz_en":"Análogo de factor liberador de hormona del crecimiento sintético investigado en ensayos clínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 18057338","titel_en":"PubMed: Publicación de investigación, PMID 18057338","url":"https://pubmed.ncbi.nlm.nih.gov/18057338/"}],"text":"El artículo clínico citado investiga un factor liberador de hormona del crecimiento en personas con VIH. El contexto clínico y la preparación del estudio limitan cómo se pueden generalizar los hallazgos.","text_en":"El artículo clínico citado investiga un factor liberador de hormona del crecimiento en personas con VIH. El contexto clínico y la preparación del estudio limitan cómo se pueden generalizar los hallazgos.","synonyme":["Egrifta","TH9507","Egrifta WR"],"synonyme_en":["Egrifta","TH9507","Egrifta WR"],"link":"wirkstoffe/tesamorelin.html"},{"slug":"thymosin-alpha-1","begriff":"Timosina alfa 1","begriff_en":"Timosina alfa 1","kategorie":"wirkstoff","kurz":"Péptido del sistema timosina investigado en estudios clínicos y preclínicos.","kurz_en":"Péptido del sistema timosina investigado en estudios clínicos y preclínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 3998766","titel_en":"PubMed: Publicación de investigación, PMID 3998766","url":"https://pubmed.ncbi.nlm.nih.gov/3998766/"}],"text":"El ensayo aleatorizado enlazado investiga timosina alfa-1 sintética en un contexto oncológico particular. Tal hallazgo no es evidencia general de potenciación inmunológica y no verifica productos de investigación comercializados libremente.","text_en":"El ensayo aleatorizado enlazado investiga timosina alfa-1 sintética en un contexto oncológico particular. Tal hallazgo no es evidencia general de potenciación inmunológica y no verifica productos de investigación comercializados libremente.","synonyme":["Tα1","Zadaxin (nombre comercial)"],"synonyme_en":["Tα1","Zadaxin (nombre comercial)"],"link":"wirkstoffe/thymosin-alpha-1.html"},{"slug":"thymosine","begriff":"Timosinas","begriff_en":"Timosinas","kategorie":"klassen","kurz":"Las timosinas son una familia de péptidos aislados originalmente de la glándula tímica.","kurz_en":"Las timosinas son una familia de péptidos aislados originalmente de la glándula tímica.","quellen":[{"titel":"NCI: Timosinas","titel_en":"NCI: Timosinas","url":"https://www.cancer.gov/publications/dictionaries/cancer-drug/def/recombinant-thymosin"}],"text":"El nombre abarca diferentes péptidos aislados originalmente de material tímico. Las timosinas alfa y beta difieren en estructura y contexto de investigación. Los hallazgos para una timosina no se aplican automáticamente a otras.","text_en":"El nombre abarca diferentes péptidos aislados originalmente de material tímico. Las timosinas alfa y beta difieren en estructura y contexto de investigación. Los hallazgos para una timosina no se aplican automáticamente a otras.","synonyme":["Péptidos de timosina"],"synonyme_en":["Péptidos de timosina"],"siehe":["peptidhormon","protein"],"wirkstoffe":["thymosin-alpha-1","tb-500"],"seiten":["peptid-1x1.html"]},{"slug":"tiermodell","begriff":"Modelo animal","begriff_en":"Modelo animal","kategorie":"studien","kurz":"Un animal de laboratorio, como un ratón o rata, se utiliza para estudiar una sustancia in vivo. No es prueba directa para humanos.","kurz_en":"Un animal de laboratorio, como un ratón o rata, se utiliza para estudiar una sustancia in vivo. No es prueba directa para humanos.","quellen":[{"titel":"NCI: modelo animal","titel_en":"NCI: modelo animal","url":"https://www.cancer.gov/publications/dictionaries/cancer-terms/def/animal-model"}],"text":"Un modelo animal es un animal de laboratorio como un ratón, rata o pez cebra en el que se estudia el metabolismo, el comportamiento o el tejido en condiciones controladas. Sirve para investigación preclínica antes de un posible ensayo clínico. Debido a que la genética y la fisiología difieren, un efecto en un modelo animal no es prueba de un efecto en humanos.","text_en":"Un modelo animal es un animal de laboratorio como un ratón, rata o pez cebra en el que se estudia el metabolismo, el comportamiento o el tejido en condiciones controladas. Sirve para investigación preclínica antes de un posible ensayo clínico. Debido a que la genética y la fisiología difieren, un efecto en un modelo animal no es prueba de un efecto en humanos.","siehe":["in-vivo","praeklinisch"],"seiten":["studien.html"]},{"slug":"tirzepatid","begriff":"Tirzepatida","begriff_en":"Tirzepatida","kategorie":"wirkstoff","kurz":"Agonista dual de receptor GIP y GLP-1 estudiado en ensayos clínicos.","kurz_en":"Agonista dual de receptor GIP y GLP-1 estudiado en ensayos clínicos.","quellen":[{"titel":"PubMed: Publicación de investigación, PMID 35658024","titel_en":"PubMed: Publicación de investigación, PMID 35658024","url":"https://pubmed.ncbi.nlm.nih.gov/35658024/"}],"text":"El ensayo clínico aleatorizado enlazado investiga tirzepatida en la obesidad. Su formulación de estudio y controles de calidad deben distinguirse de los productos químicos de investigación comercializados libremente.","text_en":"El ensayo clínico aleatorizado enlazado investiga tirzepatida en la obesidad. Su formulación de estudio y controles de calidad deben distinguirse de los productos químicos de investigación comercializados libremente.","synonyme":["LY3298176"],"synonyme_en":["LY3298176"],"link":"wirkstoffe/tirzepatid.html"},{"slug":"u-100","begriff":"U-100","begriff_en":"U-100","kategorie":"handhabung","kurz":"Designación para insulina que contiene 100 unidades por mililitro, no una unidad de péptido general.","kurz_en":"Designación para insulina que contiene 100 unidades por mililitro, no una unidad de péptido general.","quellen":[{"titel":"DailyMed: Significado de la designación U-100","titel_en":"DailyMed: Significado de la designación U-100","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c8ecbd7a-0e22-4fc7-a503-faa58c1b6f3f"}],"text":"U-100 es una designación de concentración para productos de insulina. No es una unidad general de masa de péptido. Una escala etiquetada de esta manera no se puede interpretar como una cantidad de péptido sin conocer la sustancia y su especificación.","text_en":"U-100 es una designación de concentración para productos de insulina. No es una unidad general de masa de péptido. Una escala etiquetada de esta manera no se puede interpretar como una cantidad de péptido sin conocer la sustancia y su especificación.","siehe":["internationale-einheit","konzentration"]},{"slug":"vial","begriff":"Vial","begriff_en":"Vial","kategorie":"handhabung","kurz":"Un vial es un pequeño recipiente de vidrio, generalmente sellado con un tapón de caucho, que contiene un péptido en forma de polvo o solución.","kurz_en":"Un vial es un pequeño recipiente de vidrio, generalmente sellado con un tapón de caucho, que contiene un péptido en forma de polvo o solución.","quellen":[{"titel":"ICH Q7: Fabricación, lotes y certificados de análisis","titel_en":"ICH Q7: Fabricación, lotes y certificados de análisis","url":"https://www.fda.gov/media/71518/download"}],"text":"Los viales son el embalaje estándar para péptidos liofilizados en el comercio de investigación. El tapón de caucho permite una extracción cerrada, y la etiqueta impresa generalmente lleva el número de lote y la cantidad. Un solo vial puede coincidir con un CoA siempre que el número de lote coincida.","text_en":"Los viales son el embalaje estándar para péptidos liofilizados en el comercio de investigación. El tapón de caucho permite una extracción cerrada, y la etiqueta impresa generalmente lleva el número de lote y la cantidad. Un solo vial puede coincidir con un CoA siempre que el número de lote coincida.","synonyme":["Botella pequeña"],"synonyme_en":["Botella pequeña"],"siehe":["charge","lyophilisat","aliquot"]},{"slug":"wachstumshormon","begriff":"Hormona del crecimiento","begriff_en":"Hormona del crecimiento","kategorie":"klassen","kurz":"La hormona del crecimiento es una hormona pituitaria que regula el crecimiento, el metabolismo y la composición corporal.","kurz_en":"La hormona del crecimiento es una hormona pituitaria que regula el crecimiento, el metabolismo y la composición corporal.","quellen":[{"titel":"NIDDK: Hormona del crecimiento e IGF-1","titel_en":"NIDDK: Hormona del crecimiento e IGF-1","url":"https://www.niddk.nih.gov/health-information/endocrine-diseases/acromegaly"}],"langform":"Somatotropina","langform_en":"Somatotropina","text":"La hormona del crecimiento, también llamada somatotropina o GH, es producida por células somatotróficas en la glándula pituitaria y liberada en la sangre en pulsos, controlada por GHRH, somatostatina y grelina. Regula el crecimiento longitudinal, el metabolismo muscular y de grasa y la densidad ósea, tanto directa como a través de IGF-1 del hígado. Varias clases de péptidos se dirigen a diferentes puntos a lo largo de este eje, incluida la liberación de la pituitaria anterior.","text_en":"La hormona del crecimiento, también llamada somatotropina o GH, es producida por células somatotróficas en la glándula pituitaria y liberada en la sangre en pulsos, controlada por GHRH, somatostatina y grelina. Regula el crecimiento longitudinal, el metabolismo muscular y de grasa y la densidad ósea, tanto directa como a través de IGF-1 del hígado. Varias clases de péptidos se dirigen a diferentes puntos a lo largo de este eje, incluida la liberación de la pituitaria anterior.","synonyme":["GH","HGH","Somatotropina"],"synonyme_en":["GH","HGH","Somatotropina"],"siehe":["ghrh","ghrp","igf-1"],"wirkstoffe":["cjc-1295","tesamorelin","sermorelin","ipamorelin","hexarelin"],"seiten":["peptid-1x1.html"]},{"slug":"wada","begriff":"WADA","begriff_en":"WADA","kategorie":"recht","kurz":"WADA publica una lista anual de sustancias prohibidas para el deporte que también incluye péptidos.","kurz_en":"WADA publica una lista anual de sustancias prohibidas para el deporte que también incluye péptidos.","quellen":[{"titel":"WADA: Lista actual de sustancias prohibidas","titel_en":"WADA: Lista actual de sustancias prohibidas","url":"https://www.wada-ama.org/en/prohibited-list"}],"langform":"Agencia Mundial Antidopaje","langform_en":"Agencia Mundial Antidopaje","text":"La Agencia Mundial Antidopaje coordina las reglas antidopaje en el deporte organizado y actualiza su lista de sustancias prohibidas anualmente. Varias categorías cubren hormonas peptídicas y sustancias relacionadas, independientemente de su estado legal fuera del deporte. La sustancia específica que está cubierta se establece únicamente en la lista actual de la WADA.","text_en":"La Agencia Mundial Antidopaje coordina las reglas antidopaje en el deporte organizado y actualiza su lista de sustancias prohibidas anualmente. Varias categorías cubren hormonas peptídicas y sustancias relacionadas, independientemente de su estado legal fuera del deporte. La sustancia específica que está cubierta se establece únicamente en la lista actual de la WADA.","seiten":["faq.html"]},{"slug":"zulassung","begriff":"Autorización de comercialización","begriff_en":"Autorización de comercialización","kategorie":"recht","kurz":"La autorización de comercialización es la aprobación regulatoria requerida para vender un producto medicinal en un mercado.","kurz_en":"La autorización de comercialización es la aprobación regulatoria requerida para vender un producto medicinal en un mercado.","quellen":[{"titel":"EMA: Decisiones de evaluación y autorización","titel_en":"EMA: Decisiones de evaluación y autorización","url":"https://www.ema.europa.eu/en/about-us/what-we-do/authorisation-medicines/how-ema-evaluates-medicines-human-use"}],"text":"En el procedimiento centralizado de la UE, la EMA evalúa el expediente científico. La Comisión Europea concede la autorización de comercialización. La autorización se aplica a un producto medicinal particular bajo condiciones especificadas, no a todos los productos que lleven el mismo nombre de sustancia.","text_en":"En el procedimiento centralizado de la UE, la EMA evalúa el expediente científico. La Comisión Europea concede la autorización de comercialización. La autorización se aplica a un producto medicinal particular bajo condiciones especificadas, no a todos los productos que lleven el mismo nombre de sustancia.","synonyme":["Autorización de comercialización"],"synonyme_en":["Autorización de comercialización"],"siehe":["ema","fda","arzneimittel"],"seiten":["peptid-1x1.html"]}];
